/** Viewport-sized shots of the inner pages (read-only). Output: public-after-blok3/shots */
import { test } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

const OUT = path.resolve(process.cwd(), '.tmp-responsive', process.env.PUB_OUT || 'public-after-blok3', 'shots');

interface Shot {
  name: string;
  url: string;
  w: number;
  h: number;
  scroll?: number;
  /** Optional selector to click before the shot (e.g. open the lightbox). */
  click?: string;
}

const SHOTS: Shot[] = (JSON.parse(process.env.SHOTS || 'null') as Shot[] | null) ?? [
  { name: 'gallery-375-top', url: '/gallery', w: 375, h: 812 },
  { name: 'gallery-375-grid', url: '/gallery', w: 375, h: 812, scroll: 380 },
  { name: 'gallery-375-lightbox', url: '/gallery', w: 375, h: 812, scroll: 380, click: '.pub-gt__btn' },
  { name: 'contact-375-top', url: '/contact', w: 375, h: 812 },
  { name: 'rooms-768-list', url: '/rooms', w: 768, h: 1024, scroll: 260 },
  { name: 'about-1440-top', url: '/about', w: 1440, h: 900 },
  { name: 'gallery-1440-grid', url: '/gallery', w: 1440, h: 900, scroll: 300 },
  { name: 'notfound-375', url: '/nggak-ada-halaman', w: 375, h: 812 },
];

test('blok3 shots', async ({ browser }) => {
  test.setTimeout(5 * 60 * 1000);
  fs.mkdirSync(OUT, { recursive: true });
  for (const s of SHOTS) {
    const ctx = await browser.newContext({ baseURL: 'http://localhost:5173', viewport: { width: s.w, height: s.h }, hasTouch: s.w < 768 });
    const page = await ctx.newPage();
    await page.goto(s.url, { waitUntil: 'load' });
    await page.waitForTimeout(1400);
    if (s.scroll) {
      await page.evaluate((y) => window.scrollTo(0, y), s.scroll);
      await page.waitForTimeout(900);
    }
    if (s.click) {
      await page.locator(s.click).first().click();
      await page.waitForTimeout(500);
    }
    await page.screenshot({ path: path.join(OUT, `${s.name}.png`), animations: 'disabled' });
    await ctx.close();
  }
});

/** Calendar behaviour @375 (read-only): tap day -> popup, month nav, holiday month. */
import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { loginAsAdmin } from '../e2e/helpers';

const OUT = path.resolve(process.cwd(), '.tmp-responsive', process.env.CAPTURE_OUT || 'after-C');

test('calendar mobile check', async ({ page }) => {
  fs.mkdirSync(OUT, { recursive: true });
  await loginAsAdmin(page);
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto('/dashboard/reservations/calendar?month=2026-10', { waitUntil: 'domcontentloaded' });
  await expect(page.getByRole('heading', { name: /october 2026/i })).toBeVisible({ timeout: 15000 });
  await page.waitForTimeout(1200);

  const r: Record<string, unknown> = {};
  r.pageOverflow = await page.evaluate(
    () => document.documentElement.scrollWidth > document.documentElement.clientWidth + 1,
  );
  r.gridOverflowsCard = await page.evaluate(() => {
    const g = document.querySelector('.cal-grid') as HTMLElement;
    const c = document.querySelector('.cal-card') as HTMLElement;
    return g.scrollWidth > c.clientWidth + 1;
  });
  r.cellSize = await page.evaluate(() => {
    const el = document.querySelector('.cal-cell') as HTMLElement;
    const b = el.getBoundingClientRect();
    return { w: Math.round(b.width * 10) / 10, h: Math.round(b.height) };
  });
  r.navButtons = await page.evaluate(() =>
    Array.from(document.querySelectorAll('.cal-nav button')).map((b) => {
      const x = b.getBoundingClientRect();
      return `${Math.round(x.width)}x${Math.round(x.height)}`;
    }),
  );

  // Tap Oct 1 (has reservations) -> popup.
  await page.locator('button[aria-label^="2026-10-01"]').click();
  r.popupOpens = await page
    .getByRole('dialog')
    .first()
    .isVisible()
    .catch(() => false);
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(OUT, '375-calendar-popup.png') });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  // Keyboard: focus a cell and activate with Enter.
  await page.locator('button[aria-label^="2026-10-02"]').focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(600);
  r.keyboardOpens = await page.getByRole('dialog').first().isVisible().catch(() => false);
  await page.keyboard.press('Escape');

  // Month navigation + holidays.
  await page.getByRole('button', { name: /next/i }).first().click();
  await expect(page.getByRole('heading', { name: /november 2026/i })).toBeVisible({ timeout: 10000 });
  await page.goto('/dashboard/reservations/calendar?month=2026-12', { waitUntil: 'domcontentloaded' });
  await expect(page.getByRole('heading', { name: /december 2026/i })).toBeVisible({ timeout: 15000 });
  await page.waitForTimeout(1500);
  r.holidayMarkers = await page.getByTestId('holiday-marker').count();
  await page.screenshot({ path: path.join(OUT, '375-calendar-dec.png'), fullPage: false });

  fs.writeFileSync(path.join(OUT, 'calendar-check.json'), JSON.stringify(r, null, 2));
});

/**
 * Phase 1 baseline capture (READ-ONLY).
 * Logs in with the existing e2e helper mechanism, then captures full-page
 * screenshots + layout metrics at 6 viewports for the key pages.
 * No form is ever submitted; no mutation is triggered.
 */
import { test } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { loginAsAdmin } from '../e2e/helpers';

const OUT = path.resolve(
  process.cwd(),
  '.tmp-responsive',
  process.env.CAPTURE_OUT || 'baseline',
);

interface Viewport {
  name: string;
  width: number;
  height: number;
}

const VIEWPORTS: Viewport[] = [
  { name: '375x812', width: 375, height: 812 },
  { name: '430x932', width: 430, height: 932 },
  { name: '768x1024', width: 768, height: 1024 },
  { name: '1024x768', width: 1024, height: 768 },
  { name: '1366x768', width: 1366, height: 768 },
  { name: '1440x900', width: 1440, height: 900 },
];

function sel(el: Element): string {
  const t = el.tagName.toLowerCase();
  const id = (el as HTMLElement).id;
  if (id) return `${t}#${id}`;
  const cls = ((el as HTMLElement).className as unknown) as string;
  const c = typeof cls === 'string' ? cls.trim().split(/\s+/).slice(0, 2).join('.') : '';
  return c ? `${t}.${c}` : t;
}

async function collectMetrics(page: import('@playwright/test').Page, viewport: Viewport) {
  return page.evaluate(
    ({ vw }: { vw: number }) => {
      const q = (s: string) => Array.from(document.querySelectorAll(s));
      const describe = (el: Element) => {
        const t = el.tagName.toLowerCase();
        const id = (el as HTMLElement).id;
        if (id) return `${t}#${id}`;
        const cls = (el as HTMLElement).className;
        const c = typeof cls === 'string' ? cls.trim().split(/\s+/).slice(0, 2).join('.') : '';
        return c ? `${t}.${c}` : t;
      };
      const htmlFont = getComputedStyle(document.documentElement).fontSize;
      const bodyFont = getComputedStyle(document.body).fontSize;
      const de = document.documentElement;
      const pageOverflow = de.scrollWidth > de.clientWidth + 1;

      const side = document.querySelector('.pms-side') as HTMLElement | null;
      let sidebar: Record<string, unknown> = { present: false };
      if (side) {
        const cs = getComputedStyle(side);
        const r = side.getBoundingClientRect();
        sidebar = {
          present: true,
          position: cs.position,
          widthPx: Math.round(r.width),
          shareOfViewport: +(r.width / vw).toFixed(3),
          visible: r.width > 1 && r.height > 1,
        };
      }

      const wide: Array<{ selector: string; widthPx: number }> = [];
      for (const el of q('body *')) {
        const r = (el as HTMLElement).getBoundingClientRect();
        if (r.width > vw + 1 && wide.length < 200) {
          wide.push({ selector: describe(el), widthPx: Math.round(r.width) });
        }
      }
      wide.sort((a, b) => b.widthPx - a.widthPx);

      let smallTargets = 0;
      const smallTargetSamples: string[] = [];
      for (const el of q('button, a, input, select, textarea, [role=button]')) {
        const r = (el as HTMLElement).getBoundingClientRect();
        if (r.width === 0 && r.height === 0) continue;
        if (r.width < 44 || r.height < 44) {
          smallTargets++;
          if (smallTargetSamples.length < 8) {
            smallTargetSamples.push(
              `${describe(el)} ${Math.round(r.width)}x${Math.round(r.height)}`,
            );
          }
        }
      }

      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      let smallText = 0;
      const bySel = new Map<string, number>();
      let node: Node | null = walker.nextNode();
      let guard = 0;
      while (node && guard < 20000) {
        guard++;
        const text = (node.textContent || '').trim();
        if (text.length > 0) {
          const parent = node.parentElement;
          if (parent) {
            const fs = parseFloat(getComputedStyle(parent).fontSize || '0');
            if (fs > 0 && fs < 12) {
              smallText++;
              const k = describe(parent);
              bySel.set(k, (bySel.get(k) || 0) + 1);
            }
          }
        }
        node = walker.nextNode();
      }
      const topSmallText = Array.from(bySel.entries())
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([k, v]) => `${k} x${v}`);

      const inputFonts: string[] = [];
      for (const el of q('input, select, textarea')) {
        inputFonts.push(getComputedStyle(el as Element).fontSize);
      }
      const inputMin = inputFonts.length
        ? Math.min(...inputFonts.map((f) => parseFloat(f) || 999))
        : null;

      return {
        htmlFont,
        bodyFont,
        pageOverflow,
        docScrollWidth: de.scrollWidth,
        docClientWidth: de.clientWidth,
        sidebar,
        wideElements: wide.slice(0, 10),
        wideElementsTotal: wide.length,
        smallTargets,
        smallTargetSamples,
        smallTextNodes: smallText,
        topSmallText,
        inputFonts: inputFonts.slice(0, 12),
        inputFontsMin: inputMin,
        inputBelow16: inputMin !== null && inputMin < 16,
      };
    },
    { vw: viewport.width },
  );
}

