import { useState, useEffect, type FormEvent } from 'react';
import { Button } from './Button';
import { Input } from './Input';
import roleService from '@/services/roleService';
import permissionService from '@/services/permissionService';
import { apiErrorMessage } from '@/services/api';

interface RoleFormProps {
  id?: string;
  onSuccess: () => void;
  onCancel: () => void;
}

export function RoleForm({ id, onSuccess, onCancel }: RoleFormProps) {
  const isEdit = !!id;
  const [formData, setFormData] = useState({ name: '', description: '', permissions: [] as string[] });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [serverError, setServerError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(!!id);
  const [permissions, setPermissions] = useState<any[]>([]);

  useEffect(() => {
    let cancelled = false;
    permissionService.getAll().then((p) => {
      if (!cancelled) setPermissions(p);
    }).catch(() => {
      if (!cancelled) setServerError('Failed to load permissions');
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    setIsLoading(true);
    roleService.getById(id).then((role) => {
      if (cancelled) return;
      if (role) setFormData({ name: role.name, description: role.description, permissions: role.permissions || [] });
      setIsLoading(false);
    }).catch(() => {
      if (!cancelled) {
        setServerError('Failed to load role');
        setIsLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const validate = (): boolean => {
    const errs: Record<string, string> = {};
    if (!formData.name.trim() || formData.name.trim().length < 2) errs.name = 'Name must be at least 2 characters';
    if (!formData.description.trim()) errs.description = 'Description is required';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setIsSubmitting(true);
    setServerError('');
    try {
      const data = { ...formData, status: 'active' as const };
      if (isEdit && id) {
        const result = await roleService.update(id, data);
        if (result) onSuccess();
        else setServerError('Failed to update role');
      } else {
        const result = await roleService.create(data);
        if (result) onSuccess();
      }
    } catch (err) {
      setServerError(apiErrorMessage(err, 'Failed to save role'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const togglePermission = (permName: string) => {
    setFormData((prev) => ({
      ...prev,
      permissions: prev.permissions.includes(permName)
        ? prev.permissions.filter((p) => p !== permName)
        : [...prev.permissions, permName],
    }));
  };

  if (isLoading) {
    return <p style={{ color: '#6B7881', fontSize: '14px' }}>Loading role...</p>;
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md, 12px)' }}>
      {serverError && <div role="alert" style={{ color: '#C85C5C', fontSize: '13px' }}>{serverError}</div>}
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#232D36' }}>Role Name</label>
        <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} placeholder="e.g., Manager" errorMessage={errors.name} />
        {errors.name && <span style={{ color: '#C85C5C', fontSize: '12px' }}>{errors.name}</span>}
      </div>
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#232D36' }}>Description</label>
        <textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} placeholder="Describe this role..." style={{ width: '100%', minHeight: '80px', padding: '12px 14px', backgroundColor: '#FFFFFF', border: '1px solid #C7BBAB', borderRadius: '8px', fontSize: 'var(--font-size-body, 14px)', fontFamily: 'var(--font-family-sans)', outline: 'none', boxSizing: 'border-box' }} />
        {errors.description && <span style={{ color: '#C85C5C', fontSize: '12px' }}>{errors.description}</span>}
      </div>
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#232D36' }}>Permissions</label>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: 'var(--space-xs, 4px)', maxHeight: '300px', overflowY: 'auto', border: '1px solid #C7BBAB', borderRadius: '8px', padding: 'var(--space-md, 12px)', backgroundColor: '#FFFFFF' }}>
          {permissions.map((perm: any) => (
            <label key={perm.id} style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-xs, 4px)', fontSize: 'var(--font-size-body, 14px)', cursor: 'pointer', padding: '4px' }}>
              <input type="checkbox" checked={formData.permissions.includes(perm.name)} onChange={() => togglePermission(perm.name)} />
              {perm.name}
            </label>
          ))}
        </div>
      </div>
      <div style={{ display: 'flex', gap: 'var(--space-md, 12px)', marginTop: 'var(--space-sm, 8px)', flexWrap: 'wrap' }}>
        <Button type="submit" variant="primary" disabled={isSubmitting}>{isSubmitting ? 'Saving...' : isEdit ? 'Update Role' : 'Create Role'}</Button>
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
      </div>
    </form>
  );
}

import React from 'react';

interface Column<T> {
  key: string;
  header: string;
  render?: (item: T) => React.ReactNode;
  sortable?: boolean;
}

interface TableProps<T> {
  columns: Column<T>[];
  data: T[];
  loading?: boolean;
  onRowClick?: (item: T) => void;
  emptyMessage?: string;
  density?: 'comfortable' | 'compact';
  headerStyle?: React.CSSProperties;
  selectedId?: string | null;
}

export function Table<T extends { id: string }>({
  columns,
  data,
  loading = false,
  onRowClick,
  emptyMessage = 'No data available',
  density = 'comfortable',
  headerStyle,
  selectedId,
}: TableProps<T>) {
  if (loading) {
    return (
      <div style={{ padding: '24px', textAlign: 'center' }}>
        <div style={{ color: '#6B7881' }}>Loading...</div>
      </div>
    );
  }

  if (data.length === 0) {
    return (
      <div style={{ padding: '24px', textAlign: 'center', color: '#6B7881', backgroundColor: '#FFFFFF', border: '1px solid #C7BBAB', borderRadius: '8px' }}>
        {emptyMessage}
      </div>
    );
  }

  const cellPad = density === 'compact' ? '6px 8px' : '12px 16px';
  const headFont = density === 'compact' ? '11px' : '12px';
  const bodyFont = density === 'compact' ? '13px' : '14px';

  return (
    <div className="tbl-wrap" style={{ overflowX: 'auto', borderRadius: '8px', border: '1px solid #C7BBAB', backgroundColor: '#FFFFFF', maxWidth: '100%' }}>
      <table
        className="tbl"
        style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed', ['--tbl-cols' as string]: columns.length } as React.CSSProperties}
      >
        <thead>
          <tr style={{ backgroundColor: headerStyle?.backgroundColor || '#97764D' }}>
            {columns.map((col) => (
              <th
                key={col.key}
                style={{
                  padding: cellPad,
                  textAlign: 'center',
                  fontWeight: 600,
                  fontSize: headFont,
                  textTransform: 'uppercase',
                  letterSpacing: '0.04em',
                  color: headerStyle?.color || '#FFFFFF',
                  borderBottom: '1px solid #C7BBAB',
                  overflowWrap: 'break-word',
                  ...headerStyle,
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((item, index) => {
            const isSelected = selectedId === item.id;
            const baseBg = isSelected ? '#E9E6E0' : index % 2 === 0 ? '#FFFFFF' : '#F2F0EB';
            return (
            <tr
              key={item.id || index}
              data-room-row={item.id}
              onClick={() => onRowClick?.(item)}
              onKeyDown={(e) => {
                if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
                  e.preventDefault();
                  onRowClick(item);
                }
              }}
              tabIndex={onRowClick ? 0 : undefined}
              style={{
                cursor: onRowClick ? 'pointer' : 'default',
                backgroundColor: baseBg,
                outline: isSelected ? '2px solid #97764D' : 'none',
                outlineOffset: isSelected ? '-2px' : undefined,
                transition: 'background-color 150ms ease',
              }}
              onMouseEnter={(e) => {
                if (!isSelected) {
                  (e.currentTarget as HTMLElement).style.backgroundColor = '#E9E6E0';
                }
              }}
              onMouseLeave={(e) => {
                if (!isSelected) {
                  (e.currentTarget as HTMLElement).style.backgroundColor = baseBg;
                }
              }}
              onFocus={(e) => {
                if (onRowClick) {
                  (e.currentTarget as HTMLElement).style.outline = '2px solid #97764D';
                  (e.currentTarget as HTMLElement).style.outlineOffset = '-2px';
                }
              }}
              onBlur={(e) => {
                (e.currentTarget as HTMLElement).style.outline = isSelected ? '2px solid #97764D' : 'none';
              }}
            >
              {columns.map((col) => (
                <td
                  key={col.key}
                  style={{
                    padding: cellPad,
                    borderBottom: '1px solid #E3DED6',
                    fontSize: bodyFont,
                    color: '#232D36',
                    textAlign: 'center',
                    overflowWrap: 'break-word',
                  }}
                >
                  {col.render ? col.render(item) : (item as any)[col.key]}
                </td>
              ))}
             </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

import { useState, useEffect, useMemo, type FormEvent } from 'react';
import { Button } from './Button';
import { Input } from './Input';
import { Select } from './Select';
import userService from '@/services/userService';
import roleService from '@/services/roleService';
import { ApiError, apiErrorMessage } from '@/services/api';
import { useAuth } from '@/hooks/useAuth';
import { usePermissions } from '@/hooks/usePermissions';
import { STATIC_PERMISSION_CATALOG } from '@/config/permissions';
import { PermissionCheckboxGrid, type PermissionOption } from './PermissionCheckboxGrid';
import permissionService from '@/services/permissionService';
import {
  computeEffectivePermissions,
  computeOverrideUpdate,
  getUserPermissionOverride,
  setUserPermissionOverride,
} from '@/services/userPermissionService';

/** Granting this permission lets the holder escalate anyone (mirrors the
 * backend `assertNoPrivilegeEscalation` rule), so only its current holders
 * may hand it out. */
const ASSIGN_GATED = 'permission.assign';

interface UserFormProps {
  id?: string;
  onSuccess: () => void;
  onCancel: () => void;
}

export function UserForm({ id, onSuccess, onCancel }: UserFormProps) {
  const isEdit = !!id;
  const { user: currentUser } = useAuth();
  const { hasPermission, refreshPermissions } = usePermissions();
  const [formData, setFormData] = useState<{ name: string; email: string; password: string; roles: string[]; status: 'active' | 'inactive' }>({ name: '', email: '', password: '', roles: [], status: 'active' });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [serverError, setServerError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(!!id);
  const [roles, setRoles] = useState<any[]>([]);
  const [catalog, setCatalog] = useState<PermissionOption[]>([]);
  const [permDraft, setPermDraft] = useState<{ grants: string[]; denies: string[] }>({ grants: [], denies: [] });

  // Only holders of user.update may assign individual permissions, and nobody
  // may edit their own overrides (prevents self lock-out / self escalation).
  const canManagePermissions = hasPermission('user.update');
  const canGrantAssign = hasPermission(ASSIGN_GATED);
  const isSelf = isEdit && !!id && !!currentUser && id === currentUser.id;

  // Role-derived baseline for the roles currently selected in this form.
  const rolePerms = useMemo(() => {
    const set = new Set<string>();
    for (const r of roles) {
      if (formData.roles.includes(r.id) && Array.isArray(r.permissions)) {
        for (const p of r.permissions) {
          if (typeof p === 'string') set.add(p);
        }
      }
    }
    return [...set];
  }, [roles, formData.roles]);

  const effectivePreview = useMemo(
    () => computeEffectivePermissions(rolePerms, permDraft),
    [rolePerms, permDraft],
  );

  useEffect(() => {
    let cancelled = false;
    roleService.getAll().then((r) => {
      if (!cancelled) setRoles(r);
    }).catch(() => {
      if (!cancelled) setServerError('Failed to load roles');
    });
    permissionService.getAll().then((perms) => {
      if (cancelled) return;
      const list = (Array.isArray(perms) && perms.length > 0 ? perms : STATIC_PERMISSION_CATALOG).map((p: any) => ({
        name: p.name,
        group: p.group,
        description: p.description,
      }));
      setCatalog(list.filter((p) => typeof p.name === 'string'));
    }).catch(() => {
      if (!cancelled) {
        setCatalog(STATIC_PERMISSION_CATALOG);
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    setIsLoading(true);
    userService.getById(id).then((user) => {
      if (cancelled) return;
      if (user) {
        setFormData({ name: user.name, email: user.email, password: '', roles: user.roles || [], status: user.status });
      }
      setIsLoading(false);
    }).catch(() => {
      if (!cancelled) {
        setServerError('Failed to load user');
        setIsLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [id]);

  useEffect(() => {
    if (!id) {
      setPermDraft({ grants: [], denies: [] });
      return;
    }
    let cancelled = false;
    getUserPermissionOverride(id).then((o) => {
      if (!cancelled) setPermDraft({ grants: o.grants, denies: o.denies });
    });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const toggleUserPermission = (name: string, checked: boolean) => {
    setPermDraft((prev) => computeOverrideUpdate(rolePerms, prev, name, checked));
  };

  const validate = (): boolean => {
    const errs: Record<string, string> = {};
    if (!formData.name.trim() || formData.name.trim().length < 2) errs.name = 'Name must be at least 2 characters';
    if (!formData.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) errs.email = 'Valid email required';
    if (!isEdit && (!formData.password || formData.password.length < 6)) errs.password = 'Password must be at least 6 characters';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!validate()) return;
    setIsSubmitting(true);
    setServerError('');
    try {
      const data = { name: formData.name, email: formData.email, status: formData.status, roles: formData.roles };
      if (isEdit && id) {
        const result = await userService.update(id, data);
        if (result) {
          if (canManagePermissions && !isSelf) {
            await setUserPermissionOverride(id, permDraft);
            await refreshPermissions();
          }
          onSuccess();
        } else setServerError('Failed to update user');
      } else {
        const result = await userService.create({ ...data, password: formData.password || 'password123' });
        if (result) {
          if (canManagePermissions && result.id) {
            await setUserPermissionOverride(result.id, permDraft);
            await refreshPermissions();
          }
          onSuccess();
        }
      }
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setServerError(err.message);
      } else {
        setServerError(apiErrorMessage(err, 'Failed to save user'));
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return <p style={{ color: '#6B7881', fontSize: '14px' }}>Loading user...</p>;
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md, 12px)' }}>
      {serverError && <div role="alert" style={{ color: '#C85C5C', fontSize: '13px' }}>{serverError}</div>}
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Full Name</label>
        <Input value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} placeholder="John Doe" errorMessage={errors.name} />
        {errors.name && <span style={{ color: '#C85C5C', fontSize: '12px' }}>{errors.name}</span>}
      </div>
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Email</label>
        <Input type="email" value={formData.email} onChange={(e) => setFormData({ ...formData, email: e.target.value })} placeholder="john@hotel.com" errorMessage={errors.email} />
        {errors.email && <span style={{ color: '#C85C5C', fontSize: '12px' }}>{errors.email}</span>}
      </div>
      {!isEdit && (
        <div>
          <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Password</label>
          <Input type="password" value={formData.password} onChange={(e) => setFormData({ ...formData, password: e.target.value })} placeholder="Min 6 characters" errorMessage={errors.password} />
          {errors.password && <span style={{ color: '#C85C5C', fontSize: '12px' }}>{errors.password}</span>}
        </div>
      )}
      <Select
        label="Role"
        options={[{ value: '', label: 'Select a role' }, ...roles.map((r: any) => ({ value: r.id, label: r.name }))]}
        value={formData.roles[0] || ''}
        onChange={(e) => setFormData({ ...formData, roles: [e.target.value] })}
      />
      <Select
        label="Status"
        options={[
          { value: 'active', label: 'Active' },
          { value: 'inactive', label: 'Inactive' },
        ]}
        value={formData.status}
        onChange={(e) => setFormData({ ...formData, status: e.target.value as 'active' | 'inactive' })}
      />
      {canManagePermissions && !isSelf && (
        <div>
          <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Permissions</label>
          <p style={{ fontSize: '12px', color: '#6B7881', margin: '0 0 8px' }}>
            User-specific access to existing pages and actions. Checked means this user has the permission;
            unchecking a role-provided permission revokes it for this user only.
          </p>
          <PermissionCheckboxGrid
            permissions={catalog}
            checked={(name) => effectivePreview.includes(name)}
            fromRole={(name) => rolePerms.includes(name)}
            disabled={(name) => name === ASSIGN_GATED && !canGrantAssign}
            disabledHint="permission.assign can only be granted by someone who already holds it."
            onToggle={toggleUserPermission}
          />
        </div>
      )}
      {canManagePermissions && isSelf && (
        <p style={{ fontSize: '12px', color: '#6B7881', margin: 0 }}>You cannot change your own permissions.</p>
      )}
      <div style={{ display: 'flex', gap: 'var(--space-md, 12px)', marginTop: 'var(--space-sm, 8px)', flexWrap: 'wrap' }}>
        <Button type="submit" variant="primary" disabled={isSubmitting}>{isSubmitting ? 'Saving...' : isEdit ? 'Update User' : 'Create User'}</Button>
        <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
      </div>
    </form>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Button } from './Button';
import { PermissionCheckboxGrid, type PermissionOption } from './PermissionCheckboxGrid';
import userService from '@/services/userService';
import roleService from '@/services/roleService';
import permissionService from '@/services/permissionService';
import { apiErrorMessage } from '@/services/api';
import { useAuth } from '@/hooks/useAuth';
import { usePermissions } from '@/hooks/usePermissions';
import { STATIC_PERMISSION_CATALOG } from '@/config/permissions';
import {
  computeEffectivePermissions,
  computeOverrideUpdate,
  getUserPermissionOverride,
  setUserPermissionOverride,
} from '@/services/userPermissionService';

/** Granting this permission lets the holder escalate anyone (mirrors the
 * backend `assertNoPrivilegeEscalation` rule), so only its current holders
 * may hand it out. */
const ASSIGN_GATED = 'permission.assign';

interface UserPermissionFormProps {
  userId: string;
  onSuccess: () => void;
  onCancel: () => void;
}

/**
 * Standalone permission assignment for one existing user (opened from the
 * "Assign Permission" action). Role assignment stays in UserRoleForm.
 */
export function UserPermissionForm({ userId, onSuccess, onCancel }: UserPermissionFormProps) {
  const { user: currentUser } = useAuth();
  const { hasPermission, refreshPermissions } = usePermissions();
  const [user, setUser] = useState<any | null>(null);
  const [roles, setRoles] = useState<any[]>([]);
  const [catalog, setCatalog] = useState<PermissionOption[]>([]);
  const [permDraft, setPermDraft] = useState<{ grants: string[]; denies: string[] }>({ grants: [], denies: [] });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');

  // Only holders of user.update may assign individual permissions, and nobody
  // may edit their own overrides (prevents self lock-out / self escalation).
  const canManagePermissions = hasPermission('user.update');
  const canGrantAssign = hasPermission(ASSIGN_GATED);
  const isSelf = !!currentUser && userId === currentUser.id;

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    Promise.all([
      userService.getById(userId),
      roleService.getAll().catch(() => [] as any[]),
      permissionService.getAll().catch(() => [] as any[]),
      getUserPermissionOverride(userId),
    ])
      .then(([u, r, perms, o]) => {
        if (cancelled) return;
        setUser(u ?? null);
        setRoles(r);
        const list: PermissionOption[] = (Array.isArray(perms) && perms.length > 0
          ? perms
          : STATIC_PERMISSION_CATALOG
        ).map((p: any) => ({
          name: p.name,
          group: p.group,
          description: p.description,
        }));
        setCatalog(list.filter((p) => typeof p.name === 'string'));
        setPermDraft({ grants: o.grants, denies: o.denies });
        setIsLoading(false);
      })
      .catch((err) => {
        if (!cancelled) {
          setError(apiErrorMessage(err, 'Failed to load data'));
          setIsLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [userId]);

  // Role-derived baseline for the user's current roles.
  const rolePerms = useMemo(() => {
    const set = new Set<string>();
    const userRoleIds: string[] = Array.isArray(user?.roles) ? user.roles : [];
    for (const r of roles) {
      if (userRoleIds.includes(r.id) && Array.isArray(r.permissions)) {
        for (const p of r.permissions) {
          if (typeof p === 'string') set.add(p);
        }
      }
    }
    return [...set];
  }, [roles, user]);

  const effectivePreview = useMemo(
    () => computeEffectivePermissions(rolePerms, permDraft),
    [rolePerms, permDraft],
  );

  const toggleUserPermission = (name: string, checked: boolean) => {
    setPermDraft((prev) => computeOverrideUpdate(rolePerms, prev, name, checked));
  };

  const handleSave = async () => {
    if (isSaving) return;
    setIsSaving(true);
    setError('');
    try {
      await setUserPermissionOverride(userId, permDraft);
      await refreshPermissions();
      onSuccess();
    } catch (err) {
      setError(apiErrorMessage(err, 'Failed to save permissions'));
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <p style={{ color: '#6B7881', fontSize: '14px' }}>Loading...</p>;
  }

  if (!user) return null;

  if (!canManagePermissions || isSelf) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md, 12px)' }}>
        <div style={{ backgroundColor: '#FFFFFF', border: '1px solid #C7BBAB', borderRadius: '8px', padding: 'var(--space-xl, 20px)' }}>
          <p style={{ fontWeight: 600, color: '#232D36', margin: 0 }}>{user.name}</p>
          <p style={{ fontSize: '13px', color: '#6B7881', margin: '4px 0 0' }}>{user.email}</p>
        </div>
        <p style={{ fontSize: '12px', color: '#6B7881', margin: 0 }}>
          {isSelf
            ? 'You cannot change your own permissions.'
            : 'You need the user.update permission to assign permissions.'}
        </p>
        <div style={{ display: 'flex', gap: 'var(--space-md, 12px)', flexWrap: 'wrap' }}>
          <Button variant="outline" onClick={onCancel}>Close</Button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md, 12px)' }}>
      {error && <div role="alert" style={{ color: '#C85C5C', fontSize: '13px' }}>{error}</div>}
      <div style={{ backgroundColor: '#FFFFFF', border: '1px solid #C7BBAB', borderRadius: '8px', padding: 'var(--space-xl, 20px)' }}>
        <p style={{ fontWeight: 600, color: '#232D36', margin: 0 }}>{user.name}</p>
        <p style={{ fontSize: '13px', color: '#6B7881', margin: '4px 0 0' }}>{user.email}</p>
      </div>
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Permissions</label>
        <p style={{ fontSize: '12px', color: '#6B7881', margin: '0 0 8px' }}>
          User-specific access to existing pages and actions. Checked means this user has the permission;
          unchecking a role-provided permission revokes it for this user only.
        </p>
        <PermissionCheckboxGrid
          permissions={catalog}
          checked={(name) => effectivePreview.includes(name)}
          fromRole={(name) => rolePerms.includes(name)}
          disabled={(name) => name === ASSIGN_GATED && !canGrantAssign}
          disabledHint="permission.assign can only be granted by someone who already holds it."
          onToggle={toggleUserPermission}
        />
      </div>
      <div style={{ display: 'flex', gap: 'var(--space-md, 12px)', flexWrap: 'wrap' }}>
        <Button variant="primary" onClick={handleSave} disabled={isSaving}>{isSaving ? 'Saving...' : 'Save Permissions'}</Button>
        <Button variant="outline" onClick={onCancel}>Cancel</Button>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Button } from './Button';
import { Select } from './Select';
import userService from '@/services/userService';
import roleService from '@/services/roleService';
import { apiErrorMessage } from '@/services/api';
import { useAuth } from '@/hooks/useAuth';
import { usePermissions } from '@/hooks/usePermissions';
import { STATIC_PERMISSION_CATALOG } from '@/config/permissions';
import { PermissionCheckboxGrid, type PermissionOption } from './PermissionCheckboxGrid';
import permissionService from '@/services/permissionService';
import {
  computeEffectivePermissions,
  computeOverrideUpdate,
  getUserPermissionOverride,
  setUserPermissionOverride,
} from '@/services/userPermissionService';

/** Granting this permission lets the holder escalate anyone (mirrors the
 * backend `assertNoPrivilegeEscalation` rule), so only its current holders
 * may hand it out. */
const ASSIGN_GATED = 'permission.assign';

interface UserRoleFormProps {
  userId: string;
  onSuccess: () => void;
  onCancel: () => void;
}

export function UserRoleForm({ userId, onSuccess, onCancel }: UserRoleFormProps) {
  const { user: currentUser } = useAuth();
  const { hasPermission, refreshPermissions } = usePermissions();
  const [user, setUser] = useState<any | null>(null);
  const [roles, setRoles] = useState<any[]>([]);
  const [selectedRole, setSelectedRole] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [permDraft, setPermDraft] = useState<{ grants: string[]; denies: string[] }>({ grants: [], denies: [] });
  const [catalog, setCatalog] = useState<PermissionOption[]>([]);

  // Only holders of user.update may assign individual permissions, and nobody
  // may edit their own overrides (prevents self lock-out / self escalation).
  const canManagePermissions = hasPermission('user.update');
  const canGrantAssign = hasPermission(ASSIGN_GATED);
  const isSelf = !!currentUser && userId === currentUser.id;

  // Role-derived baseline for the currently selected role.
  const rolePerms = useMemo(() => {
    const role = roles.find((r: any) => r.id === selectedRole);
    return Array.isArray(role?.permissions) ? role.permissions.filter((p: unknown) => typeof p === 'string') : [];
  }, [roles, selectedRole]);

  const effectivePreview = useMemo(
    () => computeEffectivePermissions(rolePerms, permDraft),
    [rolePerms, permDraft],
  );

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    Promise.all([userService.getById(userId), roleService.getAll()])
      .then(([u, r]) => {
        if (cancelled) return;
        setUser(u ?? null);
        setRoles(r);
        if (u && Array.isArray(u.roles) && u.roles.length > 0) setSelectedRole(u.roles[0]);
        setIsLoading(false);
      })
      .catch((err) => {
        if (!cancelled) {
          setError(apiErrorMessage(err, 'Failed to load data'));
          setIsLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [userId]);

  useEffect(() => {
    let cancelled = false;
    setPermDraft({ grants: [], denies: [] });
    Promise.all([
      permissionService.getAll().catch(() => [] as any[]),
      getUserPermissionOverride(userId),
    ]).then(([perms, o]) => {
      if (cancelled) return;
      const list: PermissionOption[] = (Array.isArray(perms) && perms.length > 0
        ? perms
        : STATIC_PERMISSION_CATALOG
      ).map((p: any) => ({ name: p.name, group: p.group, description: p.description }));
      setCatalog(list.filter((p) => typeof p.name === 'string'));
      setPermDraft({ grants: o.grants, denies: o.denies });
    });
    return () => {
      cancelled = true;
    };
  }, [userId]);

  const toggleUserPermission = (name: string, checked: boolean) => {
    setPermDraft((prev) => computeOverrideUpdate(rolePerms, prev, name, checked));
  };

  const handleSave = async () => {
    if (!selectedRole || isSaving) return;
    setIsSaving(true);
    setError('');
    try {
      await userService.update(userId, { roles: [selectedRole] });
      if (canManagePermissions && !isSelf) {
        await setUserPermissionOverride(userId, permDraft);
        await refreshPermissions();
      }
      onSuccess();
    } catch (err) {
      setError(apiErrorMessage(err, 'Failed to assign role'));
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <p style={{ color: '#6B7881', fontSize: '14px' }}>Loading...</p>;
  }

  if (!user) return null;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md, 12px)' }}>
      {error && <div role="alert" style={{ color: '#C85C5C', fontSize: '13px' }}>{error}</div>}
      <div style={{ backgroundColor: '#FFFFFF', border: '1px solid #C7BBAB', borderRadius: '8px', padding: 'var(--space-xl, 20px)' }}>
        <div style={{ display: 'flex', gap: 'var(--space-lg, 16px)', flexWrap: 'wrap' }}>
          <div>
            <span style={{ fontSize: 'var(--font-size-caption, 12px)', color: '#6B7881' }}>Name</span>
            <p style={{ fontWeight: 600, color: '#232D36', margin: 0 }}>{user.name}</p>
          </div>
          <div>
            <span style={{ fontSize: 'var(--font-size-caption, 12px)', color: '#6B7881' }}>Email</span>
            <p style={{ fontWeight: 600, color: '#232D36', margin: 0 }}>{user.email}</p>
          </div>
          <div>
            <span style={{ fontSize: 'var(--font-size-caption, 12px)', color: '#6B7881' }}>Status</span>
            <p style={{ fontWeight: 600, color: '#232D36', margin: 0 }}>{user.status}</p>
          </div>
        </div>
      </div>
      <div>
        <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#232D36' }}>Role</label>
        <Select value={selectedRole} onChange={(e) => setSelectedRole(e.target.value)} options={[{ value: '', label: 'Select a role' }, ...roles.map((r: any) => ({ value: r.id, label: r.name }))]} />
      </div>
      {canManagePermissions && !isSelf && (
        <div>
          <label style={{ display: 'block', fontSize: 'var(--font-size-body, 14px)', fontWeight: 500, marginBottom: 'var(--space-xs, 4px)', color: '#6B7881' }}>Permissions</label>
          <p style={{ fontSize: '12px', color: '#6B7881', margin: '0 0 8px' }}>
            User-specific access to existing pages and actions. Checked means this user has the permission;
            unchecking a role-provided permission revokes it for this user only.
          </p>
          <PermissionCheckboxGrid
            permissions={catalog}
            checked={(name) => effectivePreview.includes(name)}
            fromRole={(name) => rolePerms.includes(name)}
            disabled={(name) => name === ASSIGN_GATED && !canGrantAssign}
            disabledHint="permission.assign can only be granted by someone who already holds it."
            onToggle={toggleUserPermission}
          />
        </div>
      )}
      {canManagePermissions && isSelf && (
        <p style={{ fontSize: '12px', color: '#6B7881', margin: 0 }}>You cannot change your own permissions.</p>
      )}
      <div style={{ display: 'flex', gap: 'var(--space-md, 12px)', flexWrap: 'wrap' }}>
        <Button variant="primary" onClick={handleSave} disabled={isSaving}>{isSaving ? 'Saving...' : 'Save Role'}</Button>
        <Button variant="outline" onClick={onCancel}>Cancel</Button>
      </div>
    </div>
  );
}

