            Hubungi via WhatsApp
          </a>
        </div>
      </section>
    </div>
  );
}

import { useMemo, useState, useEffect, useRef } from 'react';
import { Filter, X, Check, ChevronRight, ChevronLeft } from 'lucide-react';
import { Button } from '@/components/shared/Button';
import { Card } from '@/components/shared/Card';
import { Table } from '@/components/shared/Table';
import { Badge } from '@/components/shared/Badge';
import { Modal } from '@/components/shared/Modal';
import { expenseService } from '@/services/expenseService';
import { expenseCategories, expenseCategoryLabels, expenseStatusLabels } from '@/constants/expenseCategories';
import { ExpenseForm } from '@/components/shared/ExpenseForm';
import '../../styles/finance-responsive.css';
import '../../styles/reservation-list.css';

const FILTER_CATEGORIES = [
  {
    key: 'category',
    label: 'Category',
    options: [
      { value: 'all', label: 'All Categories' },
      ...expenseCategories.map((c) => ({ value: c, label: expenseCategoryLabels[c] })),
    ],
  },
  {
    key: 'status',
    label: 'Status',
    options: [
      { value: 'all', label: 'All Status' },
      { value: 'Paid', label: 'Paid' },
      { value: 'Pending', label: 'Pending' },
    ],
  },
];

export default function ExpensesPage() {
  const service = expenseService;
  const [showForm, setShowForm] = useState(false);
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [filterOpen, setFilterOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [draft, setDraft] = useState<Record<string, string>>({ category: 'all', status: 'all' });
  const filterWrapRef = useRef<HTMLDivElement>(null);
  const expenses = service.getAll();

  const filteredExpenses = useMemo(() => {
    let result = expenses;
    if (categoryFilter !== 'all') {
      result = result.filter((e) => e.category === categoryFilter);
    }
    if (statusFilter !== 'all') {
      result = result.filter((e) => e.status === statusFilter);
    }
    return result;
  }, [expenses, categoryFilter, statusFilter]);

  const activeFilterCount = (categoryFilter !== 'all' ? 1 : 0) + (statusFilter !== 'all' ? 1 : 0);

  const applyFilters = () => {
    setCategoryFilter(draft.category);
    setStatusFilter(draft.status);
    setFilterOpen(false);
  };

  const resetFilters = () => {
    setDraft({ category: 'all', status: 'all' });
    setCategoryFilter('all');
    setStatusFilter('all');
    setActiveCategory(null);
  };

  const closeFilter = () => {
    setFilterOpen(false);
    setActiveCategory(null);
  };

  useEffect(() => {
    if (!filterOpen) return;
    const onDocClick = (e: MouseEvent) => {
      if (filterWrapRef.current && !filterWrapRef.current.contains(e.target as Node)) {
        closeFilter();
      }
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [filterOpen]);

  const totalAmount = filteredExpenses.reduce((sum, e) => sum + e.amount, 0);

  const columns = [
    { key: 'date', header: 'Date', render: (item: any) => item.date },
    { key: 'category', header: 'Category', render: (item: any) => <Badge variant="default">{expenseCategoryLabels[item.category] || item.category}</Badge> },
    { key: 'description', header: 'Description', render: (item: any) => item.description },
    { key: 'amount', header: 'Amount', render: (item: any) => `Rp ${item.amount.toLocaleString('id-ID')}` },
    { key: 'status', header: 'Status', render: (item: any) => <Badge variant={item.status === 'Paid' ? 'success' : 'warning'}>{expenseStatusLabels[item.status] || item.status}</Badge> },
  ];

  return (
    <div className="fin-page">
      <div className="fin-head" style={{ marginBottom: '20px' }}>
        <h1 className="fin-h1" style={{ marginBottom: 0 }}>Expenses</h1>
        <Button onClick={() => setShowForm(true)}>+ New Expense</Button>
      </div>
      {showForm && (
        <Modal open={showForm} onClose={() => setShowForm(false)} title="New Expense" size="md">
          <ExpenseForm
            onSubmit={(data) => {
              service.create({
                category: data.category,
                description: data.description,
                amount: data.amount,
                date: data.date,
                status: data.status,
              });
              setShowForm(false);
            }}
            onCancel={() => setShowForm(false)}
          />
        </Modal>
      )}
      <div className="res-toolbar" role="search" style={{ marginBottom: '20px' }}>
        <div className="res-toolbar__filterwrap" ref={filterWrapRef}>
          <Button
            onClick={() => (filterOpen ? closeFilter() : setFilterOpen(true))}
            aria-expanded={filterOpen}
            aria-controls="expense-filter-panel"
            aria-label={activeFilterCount > 0 ? `Filter, ${activeFilterCount} active` : 'Filter'}
          >
            <Filter size={16} aria-hidden="true" />
            <span style={{ marginLeft: '8px' }}>Filter</span>
            {activeFilterCount > 0 && (
              <span className="res-filterbtn-count" aria-hidden="true">{activeFilterCount}</span>
            )}
          </Button>

          {filterOpen && (
            <>
              <button
                type="button"
                className="res-filter-scrim"
                aria-label="Close filters"
                onClick={closeFilter}
                tabIndex={-1}
              />
              <div className={`res-cascade${activeCategory ? ' res-cascade--split res-cascade--detail' : ''}`}>
                <div className="res-cascade__panel1" role="dialog" aria-label="Expense filters">
                  <div className="res-cascade__head">
                    <h2 className="res-cascade__title">Filter</h2>
                    <button
                      type="button"
                      onClick={closeFilter}
                      aria-label="Close filters"
                      className="res-cascade__close"
                    >
                      <X size={18} aria-hidden="true" />
                    </button>
                  </div>
                  <ul className="res-cascade__cats">
                    {FILTER_CATEGORIES.map((cat) => {
                      const active = draft[cat.key] !== 'all';
                      const selected = activeCategory === cat.key;
                      return (
                        <li key={cat.key}>
                          <button
                            type="button"
                            className={`res-cascade__catbtn${active ? ' res-cascade__catbtn--active' : ''}`}
                            aria-expanded={selected}
                            onClick={() => setActiveCategory(selected ? null : cat.key)}
                          >
                            <span className="res-cascade__catlabel">{cat.label}</span>
                            {active && (
                              <span className="res-cascade__catsub">
                                {cat.options.find((o) => o.value === draft[cat.key])?.label}
                              </span>
                            )}
                            <span className="res-cascade__chev" aria-hidden="true">
                              <ChevronRight size={16} aria-hidden="true" />
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                  <div className="res-cascade__actions">
                    <Button variant="outline" onClick={resetFilters}>Reset</Button>
                    <Button onClick={applyFilters}>Apply</Button>
                  </div>
                </div>

                {activeCategory && (
                  <div className="res-cascade__panel2" aria-label={`${FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label} options`}>
                    <div className="res-cascade__head">
                      <button
                        type="button"
                        onClick={() => setActiveCategory(null)}
                        aria-label="Back to filter categories"
                        className="res-cascade__back"
                      >
                        <ChevronLeft size={18} aria-hidden="true" />
                        {FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label}
                      </button>
                      <h3 className="res-cascade__title">{FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label}</h3>
                      <button
                        type="button"
                        onClick={closeFilter}
                        aria-label="Close filters"
                        className="res-cascade__close"
                      >
                        <X size={18} aria-hidden="true" />
                      </button>
                    </div>
                    <ul className="res-cascade__opts">
                      {FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.options.map((opt) => {
                        const selected = draft[activeCategory] === opt.value;
                        return (
                          <li key={opt.value}>
                            <button
                              type="button"
                              className="res-cascade__optbtn"
                              aria-pressed={selected}
                              onClick={() => setDraft({ ...draft, [activeCategory]: opt.value })}
                            >
                              <span className="res-cascade__optlabel">{opt.label}</span>
                              {selected && (
                                <span className="res-cascade__check" aria-hidden="true">
                                  <Check size={16} aria-hidden="true" />
                                </span>
                              )}
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                    <div className="res-cascade__actions2">
                      <Button variant="outline" onClick={resetFilters}>Reset</Button>
                      <Button onClick={applyFilters}>Apply</Button>
                    </div>
                  </div>
                )}
              </div>
            </>
          )}
        </div>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'center', marginLeft: 'auto' }}>
          <span className="fin-count">{filteredExpenses.length} expenses</span>
          <span className="fin-total">
            Total: Rp {totalAmount.toLocaleString('id-ID')}
          </span>
        </div>
      </div>
      <Card>
        <Table columns={columns} data={filteredExpenses} emptyMessage="Tidak ada pengeluaran ditemukan" />
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Printer } from 'lucide-react';
import { invoiceService } from '@/services/invoiceService';
import { reservationSourceLabels } from '@/constants/reservationStatuses';
import { Button } from '@/components/shared/Button';
import { Card } from '@/components/shared/Card';
import { Badge } from '@/components/shared/Badge';
import { InvoiceStatusBadge } from '@/components/shared/InvoiceStatusBadge';
import { ConfirmDialog } from '@/components/shared/ConfirmDialog';
import { InvoicePrintDocument } from '@/components/shared/InvoicePrintDocument';
import '../../styles/finance-responsive.css';
import '../../styles/invoice-print.css';

export default function InvoiceDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [confirmCancel, setConfirmCancel] = useState(false);
  const invoice = id ? invoiceService.getById(id) : undefined;

  if (!invoice) {
    return (
      <div style={{ padding: 'var(--space-xl, 20px)', textAlign: 'center' }}>
        <h2 style={{ color: '#232D36', fontFamily: 'var(--font-family-sans)' }}>Invoice not found</h2>
        <Button onClick={() => navigate('/dashboard/finance/invoices')}>Back to Invoices</Button>
      </div>
    );
  }

  const canSend = invoice.invoiceStatus === 'Draft';
  const canMarkPaid = invoice.invoiceStatus === 'Draft';
  const canCancel = invoice.invoiceStatus === 'Draft' || invoice.invoiceStatus === 'Sent';

  return (
    <div className="fin-page" style={{ maxWidth: '900px' }}>
      <div className="fin-head" style={{ marginBottom: '20px' }}>
        <Button variant="outline" onClick={() => navigate('/dashboard/finance/invoices')}><ArrowLeft size={14} aria-hidden="true" /> Back</Button>
        <h1 className="fin-h1" style={{ marginBottom: 0 }}>
          {invoice.invoiceNumber}
        </h1>
        <Button variant="outline" onClick={() => window.print()} aria-label={`Print ${invoice.invoiceNumber}`}>
          <Printer size={14} aria-hidden="true" /> Print Invoice
        </Button>
      </div>
      <Card style={{ marginBottom: '16px' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px' }}>
          <div>
            <h4 style={{ margin: '0 0 4px 0', fontSize: '12px', color: '#6B7881', textTransform: 'uppercase' }}>Guest</h4>
            <p style={{ margin: 0, fontSize: '16px', fontWeight: 600, color: '#232D36' }}>{invoice.guestName}</p>
          </div>
          <div>
            <h4 style={{ margin: '0 0 4px 0', fontSize: '12px', color: '#6B7881', textTransform: 'uppercase' }}>Source</h4>
            <p style={{ margin: 0, fontSize: '16px', fontWeight: 600, color: '#232D36' }}><Badge variant="default">{reservationSourceLabels[invoice.source] || invoice.source}</Badge></p>
          </div>
          <div>
            <h4 style={{ margin: '0 0 4px 0', fontSize: '12px', color: '#6B7881', textTransform: 'uppercase' }}>Date</h4>
            <p style={{ margin: 0, fontSize: '16px', fontWeight: 600, color: '#232D36' }}>{invoice.invoiceDate}</p>
          </div>

          <div>
            <h4 style={{ margin: '0 0 4px 0', fontSize: '12px', color: '#6B7881', textTransform: 'uppercase' }}>Status</h4>
            <InvoiceStatusBadge invoiceStatus={invoice.invoiceStatus} paymentStatus={invoice.paymentStatus} />
          </div>
        </div>
      </Card>
      <Card title="Invoice Items" style={{ marginBottom: '16px' }}>
        {invoice.items.map((item: any) => (
          <div key={item.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '8px 0', borderBottom: '1px solid #C7BBAB' }}>
            <div>
              <span style={{ color: '#232D36', fontWeight: 600 }}>{item.description}</span>
              <span style={{ marginLeft: '12px', fontSize: '13px', color: '#6B7881' }}>× {item.quantity}</span>
            </div>
            <span style={{ fontWeight: 600, color: '#232D36' }}>Rp {(item.quantity * item.unitPrice).toLocaleString('id-ID')}</span>
          </div>
        ))}
      </Card>
      <Card style={{ display: 'flex', justifyContent: 'flex-end', gap: '24px' }}>
        <div style={{ textAlign: 'right' }}>
          <p style={{ margin: '4px 0', color: '#6B7881' }}>Subtotal: Rp {invoice.subtotal.toLocaleString('id-ID')}</p>
          <p style={{ margin: '4px 0', color: '#6B7881' }}>Discount: {invoice.discount}%</p>
          <p style={{ margin: '4px 0', fontSize: '18px', fontWeight: 700, color: '#232D36' }}>Total: Rp {invoice.total.toLocaleString('id-ID')}</p>
        </div>
      </Card>
      {(canSend || canMarkPaid || canCancel) && (
        <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', marginTop: '16px', flexWrap: 'wrap' }}>
          {canSend && (
            <Button onClick={() => { invoiceService.send(invoice.id); navigate(0); }}>
              Mark as Sent
            </Button>
          )}
          {canMarkPaid && (
            <Button onClick={() => { invoiceService.markPaid(invoice.id); navigate(0); }}>
              Mark as Paid
            </Button>
          )}
          {canCancel && (
            <Button variant="danger" onClick={() => setConfirmCancel(true)}>
              Cancel Invoice
            </Button>
          )}
        </div>
      )}
      <ConfirmDialog
        open={confirmCancel}
        onClose={() => setConfirmCancel(false)}
        onConfirm={() => { invoiceService.cancel(invoice.id); setConfirmCancel(false); navigate(0); }}
        title="Cancel Invoice"
        message={`Are you sure you want to cancel ${invoice.invoiceNumber}? This action cannot be undone.`}
        confirmText="Yes, Cancel"
        destructive
      />
      <div className="invoice-print-area" aria-hidden="true">
        <InvoicePrintDocument invoice={invoice} />
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate, useParams, Link } from 'react-router-dom';
import { invoiceService } from '@/services/invoiceService';
import { reservationService } from '@/services/reservationService';
import { reservationSourceLabels } from '@/constants/reservationStatuses';
import { Card } from '@/components/shared/Card';
import { InvoiceForm } from '@/components/shared/InvoiceForm';
import '../../styles/finance-responsive.css';

export default function InvoiceFormPage() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const isEdit = !!id && id !== 'new';
  const [reservationId, setReservationId] = useState('');
  const [reservationCode, setReservationCode] = useState('');
  const [initialSource, setInitialSource] = useState('');
  const [initialGuest, setInitialGuest] = useState('');
  const [initialItems, setInitialItems] = useState<any[]>([]);
  const [initialTotal, setInitialTotal] = useState(0);

  useEffect(() => {
    if (isEdit && id) {
      const invoice = invoiceService.getById(id);
      if (invoice) {
        setReservationId(invoice.reservationId || '');
        setInitialSource(invoice.source);
        setInitialGuest(invoice.guestName);
        setInitialItems(invoice.items.map((item: any) => ({ description: item.description, quantity: item.quantity, unitPrice: item.unitPrice, subtotal: item.subtotal })));
        setInitialTotal(invoice.total);
      }
    } else if (!isEdit && id) {
      let cancelled = false;
      reservationService.getFullById(id).then((reservation) => {
        if (cancelled || !reservation) return;
        setReservationId(reservation.id);
        setReservationCode(reservation.reservationCode);
        setInitialSource(reservation.source);
        setInitialGuest(reservation.guestName);
        const rooms = reservation.rooms ?? [];
        const items = rooms.map((room) => ({
          description: `${room.roomNumber} - ${room.roomTypeName}`,
          quantity: 1,
          unitPrice: room.rate,
          subtotal: room.subtotal,
        }));
        setInitialItems(items);
        setInitialTotal(reservation.totalAmount);
      }).catch(() => {});
      return () => {
        cancelled = true;
      };
    }
  }, [isEdit, id]);

  const defaultValues = (isEdit && id) ? {
    invoiceNumber: invoiceService.getById(id)?.invoiceNumber || '',
    reservationId,
    guestName: initialGuest,
    source: initialSource,
    invoiceDate: invoiceService.getById(id)?.invoiceDate || new Date().toISOString().split('T')[0],
    items: initialItems.length > 0 ? initialItems : [{ description: '', quantity: 1, unitPrice: 0 }],
    discount: invoiceService.getById(id)?.discount || 0,
    invoiceStatus: (invoiceService.getById(id)?.invoiceStatus || 'Draft') as 'Draft' | 'Completed',
    paymentStatus: (invoiceService.getById(id)?.paymentStatus || 'Pending') as 'Pending' | 'Paid' | 'Overdue' | 'Partial',
  } : {
    invoiceNumber: `INV-2026-${String(invoiceService.getAll().length + 1).padStart(3, '0')}`,
    reservationId,
    guestName: initialGuest,
    source: initialSource,
    invoiceDate: new Date().toISOString().split('T')[0],
    items: initialItems.length > 0 ? initialItems : [{ description: '', quantity: 1, unitPrice: 0 }],
    discount: 0,
    invoiceStatus: 'Draft' as const,
    paymentStatus: 'Pending' as const,
  };

  return (
    <div className="fin-page" style={{ maxWidth: '900px' }}>
      <div className="fin-head" style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <Link to="/dashboard/finance/invoices" style={{ color: '#97764D', textDecoration: 'none', fontSize: '14px', fontWeight: 600 }}>← Back</Link>
          <h1 className="fin-h1" style={{ marginBottom: 0 }}>
            {isEdit ? 'Edit Invoice' : (id ? 'Invoice from Reservation' : 'Create Invoice')}
          </h1>
        </div>
        {id && !isEdit && (
          <Link to={`/dashboard/reservations/${id}`} style={{ display: 'inline-flex', alignItems: 'center', padding: '8px 16px', backgroundColor: '#FFFFFF', color: '#232D36', borderRadius: '8px', fontSize: '14px', fontWeight: 600, border: '1px solid #C7BBAB', textDecoration: 'none', cursor: 'pointer' }}>
            View Reservation →
          </Link>
        )}
      </div>
      {id && !isEdit && reservationId && (
        <Card style={{ marginBottom: '16px', backgroundColor: '#F2F0EB' }}>
          <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap', fontSize: '14px', color: '#232D36' }}>
            <span><strong>Reservation:</strong> {reservationCode || id}</span>
            <span><strong>Guest:</strong> {initialGuest}</span>
            <span><strong>Source:</strong> {reservationSourceLabels[initialSource] || initialSource}</span>
            <span><strong>Total:</strong> {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(initialTotal)}</span>
          </div>
        </Card>
      )}
      <InvoiceForm
        onSubmit={(data) => {
          const subtotal = data.items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
          if (isEdit && id) {
            const existing = invoiceService.getById(id);
            invoiceService.update(id, {
              invoiceNumber: data.invoiceNumber,
              reservationId: data.reservationId || undefined,
              guestName: data.guestName,
              source: data.source,
              invoiceDate: data.invoiceDate,
              items: data.items.map((item, index) => ({
                id: existing?.items[index]?.id || `inv-item-${Date.now()}-${index}`,
                invoiceId: id,
                description: item.description,
                quantity: item.quantity,
                unitPrice: item.unitPrice,
                subtotal: item.quantity * item.unitPrice,
              })),
              subtotal,
              discount: data.discount,
              total: subtotal - (subtotal * data.discount / 100),
              paymentStatus: data.paymentStatus,
              invoiceStatus: data.invoiceStatus,
            });
          } else {
            invoiceService.create({
              invoiceNumber: data.invoiceNumber,
              reservationId: data.reservationId || reservationId || undefined,
              guestName: data.guestName,
              source: data.source,
              invoiceDate: data.invoiceDate,
              items: data.items.map((item, index) => ({
                id: `inv-item-${Date.now()}-${index}`,
                invoiceId: '',
                description: item.description,
                quantity: item.quantity,
                unitPrice: item.unitPrice,
                subtotal: item.quantity * item.unitPrice,
              })),
              subtotal,
              discount: data.discount,
              total: subtotal - (subtotal * data.discount / 100),
              paymentStatus: data.paymentStatus,
              invoiceStatus: data.invoiceStatus,
            });
          }
          navigate('/dashboard/finance/invoices');
        }}
        onCancel={() => navigate('/dashboard/finance/invoices')}
        initialData={defaultValues}
      />
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Banknote, TrendingDown, Wallet, ReceiptText, Printer, Download, FileText } from 'lucide-react';
import { Card } from '@/components/shared/Card';
import { Button } from '@/components/shared/Button';
import { Input } from '@/components/shared/Input';
import { StatsCard } from '@/components/shared/StatsCard';
import { Table } from '@/components/shared/Table';
import { Badge } from '@/components/shared/Badge';
import { SalesChart } from '@/components/shared/SalesChart';
import { ExpenseChart } from '@/components/shared/ExpenseChart';
import { ReportPrintDocument } from '@/components/shared/ReportPrintDocument';
import { invoiceService } from '@/services/invoiceService';
import { salesService } from '@/services/salesService';
import { expenseService } from '@/services/expenseService';
import { expenseCategoryLabels, expenseCategories } from '@/constants/expenseCategories';
import { reservationSourceLabels } from '@/constants/reservationStatuses';
import { exportReportExcel, exportReportPDF, type ReportDataset } from '@/utils/reportExport';
import '../../styles/finance-responsive.css';
import '../../styles/report-print.css';

function formatCurrency(val: number): string {
  return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(val);
}

const periodOptions = [
  { value: 'today', label: 'Hari Ini' },
  { value: 'week', label: 'Minggu Ini' },
  { value: 'month', label: 'Bulan Ini' },
  { value: '6months', label: '6 Bulan' },
  { value: '1year', label: '1 Tahun' },
];

const FLAT_SERIES = ['#97764D', '#232D36', '#6B7881', '#7D6240', '#161D24', '#C7BBAB'];

function getDateRange(period: string): { start: string; end: string } {
  const today = new Date('2026-09-15');
  const formatDate = (d: Date) => d.toISOString().split('T')[0];
  switch (period) {
    case 'today': { const s = formatDate(today); return { start: s, end: s }; }
    case 'week': { const start = new Date(today); start.setDate(start.getDate() - 7); return { start: formatDate(start), end: formatDate(today) }; }
    case 'month': { const start = new Date(today.getFullYear(), today.getMonth(), 1); const end = new Date(today.getFullYear(), today.getMonth(), today.getDate()); return { start: formatDate(start), end: formatDate(end) }; }
    case '6months': { const start = new Date(today); start.setMonth(start.getMonth() - 6); return { start: formatDate(start), end: formatDate(today) }; }
    case '1year': { const start = new Date(today); start.setFullYear(start.getFullYear() - 1); return { start: formatDate(start), end: formatDate(today) }; }
    default: return { start: '2026-01-01', end: '2026-09-15' };
  }
}

export default function ReportPage() {
  const [period, setPeriod] = useState('month');
  const preset = getDateRange(period === 'custom' ? 'month' : period);
  const [startDate, setStartDate] = useState(preset.start);
  const [endDate, setEndDate] = useState(preset.end);
  const [includedCategories, setIncludedCategories] = useState<string[]>([...expenseCategories]);

  const applyPreset = (value: string) => {
    const range = getDateRange(value);
    setPeriod(value);
    setStartDate(range.start);
    setEndDate(range.end);
  };

  const handleStartChange = (value: string) => {
    setPeriod('custom');
    setStartDate(value);
  };

  const handleEndChange = (value: string) => {
    setPeriod('custom');
    setEndDate(value);
  };

  const toggleCategory = (category: string) => {
    setIncludedCategories((prev) =>
      prev.includes(category) ? prev.filter((c) => c !== category) : [...prev, category],
    );
  };

  const selectAllCategories = () => setIncludedCategories([...expenseCategories]);
  const clearAllCategories = () => setIncludedCategories([]);

  const start = startDate;
  const end = endDate;
  const rangeError = start && end && start > end ? 'Start date must be on or before the end date.' : null;

  const allSales = salesService.getAll();
  const allExpenses = expenseService.getAll();
  const allInvoices = invoiceService.getAll();

  const filteredSales = useMemo(() => {
    if (rangeError) return [];
    return allSales.filter((s) => s.date >= start && s.date <= end);
  }, [allSales, start, end, rangeError]);
  const filteredExpenses = useMemo(() => {
    if (rangeError) return [];
    return allExpenses.filter((e) => e.date >= start && e.date <= end && includedCategories.includes(e.category));
  }, [allExpenses, start, end, rangeError, includedCategories]);
  const filteredInvoices = useMemo(() => {
    if (rangeError) return [];
    return allInvoices.filter((inv) => {
      const d = new Date(inv.invoiceDate);
      return d >= new Date(start) && d <= new Date(end);
    });
  }, [allInvoices, start, end, rangeError]);

  const totalSales = filteredSales.reduce((sum, s) => sum + s.amount, 0);
  const totalExpenses = filteredExpenses.reduce((sum, e) => sum + e.amount, 0);
  const netRevenue = totalSales - totalExpenses;
  const totalInvoices = filteredInvoices.length;
  const paidInvoices = filteredInvoices.filter((inv) => inv.invoiceStatus === 'Completed').length;
  const pendingInvoices = filteredInvoices.filter((inv) => inv.invoiceStatus === 'Draft').length;
