export default function ReservationCalendarPage() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [appliedRoom, setAppliedRoom] = useState('all');
  const [appliedStatus, setAppliedStatus] = useState('all');
  const [draftRoom, setDraftRoom] = useState('all');
  const [draftStatus, setDraftStatus] = useState('all');
  const [filterOpen, setFilterOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState<CalCategoryKey | null>(null);
  const [search, setSearch] = useState('');
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [mounted, setMounted] = useState(false);
  const filterWrapRef = useRef<HTMLDivElement>(null);

  // The visible month is real "now" unless `?month=YYYY-MM` deep-links one.
  // Parsed once on mount; later navigation is driven by the prev/next buttons.
  const [month, setMonth] = useState<Date>(() => {
    const raw = searchParams.get('month');
    if (raw && /^\d{4}-\d{2}$/.test(raw)) {
      const parsed = parseISO(`${raw}-01`);
      if (isValid(parsed)) return startOfMonth(parsed);
    }
    return startOfMonth(new Date());
  });

  const handleMonthChange = useCallback(
    (next: Date) => {
      setMonth(startOfMonth(next));
      setSearchParams({ month: format(next, 'yyyy-MM') }, { replace: true });
    },
    [setSearchParams],
  );

  useEffect(() => {
    const t = window.setTimeout(() => setMounted(true), 60);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!filterOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (filterWrapRef.current && !filterWrapRef.current.contains(e.target as Node)) {
        setFilterOpen(false);
        setActiveCategory(null);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setFilterOpen(false);
        setActiveCategory(null);
      }
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [filterOpen]);

  const openFilter = () => {
    setDraftRoom(appliedRoom);
    setDraftStatus(appliedStatus);
    setActiveCategory(null);
    setFilterOpen(true);
  };

  const closeFilter = () => {
    setFilterOpen(false);
    setActiveCategory(null);
  };

  const applyFilters = () => {
    setAppliedRoom(draftRoom);
    setAppliedStatus(draftStatus);
    closeFilter();
  };

  const resetFilters = () => {
    setDraftRoom('all');
    setDraftStatus('all');
    setAppliedRoom('all');
    setAppliedStatus('all');
  };

  const [rooms, setRooms] = useState<Array<{ id: string; roomNumber: string; status: string }>>([]);
  const [reservations, setReservations] = useState<any[]>([]);

  useEffect(() => {
    let cancelled = false;
    roomService.getAll().then((rows) => {
      if (!cancelled) setRooms(rows);
    }).catch(() => {
      if (!cancelled) setRooms([]);
    });
    reservationService.getAll().then((rows) => {
      if (!cancelled) setReservations(rows);
    }).catch(() => {
      if (!cancelled) setReservations([]);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const activeRooms = rooms.filter((r) => r.status === 'active').length;
  const activeFilterCount = (appliedRoom !== 'all' ? 1 : 0) + (appliedStatus !== 'all' ? 1 : 0);

  const draftActive = (key: CalCategoryKey): boolean =>
    key === 'room' ? draftRoom !== 'all' : draftStatus !== 'all';

  const draftSummary = (key: CalCategoryKey): string => {
    if (key === 'room') {
      return draftRoom === 'all' ? '' : (rooms.find((r) => r.id === draftRoom)?.roomNumber || '');
    }
    if (draftStatus === 'all') return '';
    return CAL_STATUS_OPTIONS.find((o) => o.value === draftStatus)?.label || draftStatus;
  };

  const optionsForCategory = (key: CalCategoryKey): Array<{ value: string; label: string }> => {
    if (key === 'room') {
      return [
        { value: 'all', label: 'All Rooms' },
        ...rooms.map((r) => ({ value: r.id, label: `Room ${r.roomNumber}` })),
      ];
    }
    return CAL_STATUS_OPTIONS;
  };

  const draftValue = (key: CalCategoryKey): string => (key === 'room' ? draftRoom : draftStatus);

  const setDraftValue = (key: CalCategoryKey, value: string) => {
    if (key === 'room') setDraftRoom(value);
    else setDraftStatus(value);
  };

  const activeCategoryLabel = activeCategory === 'room' ? 'Room' : activeCategory === 'status' ? 'Status' : '';

  const statusCounts = useMemo(() => {
    const counts: Record<string, number> = { total: reservations.length };
    for (const s of STATUS_BARS.slice(1)) {
      counts[s.key] = reservations.filter((r) => r.status === s.key).length;
    }
    return counts;
  }, [reservations]);

  const maxCount = Math.max(1, ...Object.values(statusCounts));
  const chartSummary = `Distribusi reservasi. ${STATUS_BARS.map((s) => `${s.label} ${statusCounts[s.key] ?? 0}`).join(', ')}.`;

  const handleViewAll = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    setSelectedDate(null);
    navigate(`/dashboard/reservations?date=${y}-${m}-${d}`);
  };

  return (
    <div style={{ padding: 'var(--space-xl, 20px)', maxWidth: '1400px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', marginBottom: '20px' }}>
        <div>
          <h1 style={{ fontSize: '24px', fontWeight: 700, color: '#232D36', fontFamily: 'var(--font-family-sans)', margin: 0 }}>Reservation Calendar</h1>
          <p style={{ color: '#6B7881', margin: '4px 0 0 0', fontSize: '14px' }}>Visualize reservations by date</p>
        </div>
      </div>

      <div className="res-toolbar" role="search">
        <div className="res-toolbar__filterwrap" ref={filterWrapRef}>
          <Button
            onClick={() => (filterOpen ? setFilterOpen(false) : openFilter())}
            aria-expanded={filterOpen}
            aria-label={activeFilterCount > 0 ? `Filter, ${activeFilterCount} active` : 'Filter'}
          >
            <Filter size={16} aria-hidden="true" />
            <span style={{ marginLeft: '8px' }}>Filter</span>
            {activeFilterCount > 0 && (
              <span className="res-filterbtn-count" aria-hidden="true">{activeFilterCount}</span>
            )}
          </Button>

          {filterOpen && (
            <>
              <button
                type="button"
                className="res-filter-scrim"
                aria-label="Close filters"
                onClick={closeFilter}
                tabIndex={-1}
              />
              <div className={`res-cascade${activeCategory ? ' res-cascade--split res-cascade--detail' : ''}`}>
                <div className="res-cascade__panel1" role="dialog" aria-label="Calendar filters">
                  <div className="res-cascade__head">
                    <h2 className="res-cascade__title">Filter</h2>
                    <button type="button" onClick={closeFilter} aria-label="Close filters" className="res-cascade__close">
                      <X size={18} aria-hidden="true" />
                    </button>
                  </div>
                  <ul className="res-cascade__cats">
                    {CAL_CATEGORIES.map((cat) => {
                      const active = draftActive(cat.key);
                      const summary = draftSummary(cat.key);
                      const selected = activeCategory === cat.key;
                      return (
                        <li key={cat.key}>
                          <button
                            type="button"
                            className={`res-cascade__catbtn${active ? ' res-cascade__catbtn--active' : ''}`}
                            aria-expanded={selected}
                            onClick={() => setActiveCategory(selected ? null : cat.key)}
                          >
                            <span className="res-cascade__catlabel">{cat.label}</span>
                            {summary && <span className="res-cascade__catsub">{summary}</span>}
                            {active && (
                              <span className="res-cascade__check" aria-hidden="true">
                                <Check size={16} aria-hidden="true" />
                              </span>
                            )}
                            <span className="res-cascade__chev" aria-hidden="true">
                              <ChevronRight size={16} aria-hidden="true" />
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                  <div className="res-cascade__actions">
                    <Button variant="outline" onClick={resetFilters}>Reset</Button>
                    <Button onClick={applyFilters}>Apply</Button>
                  </div>
                </div>

                {activeCategory && (
                  <div className="res-cascade__panel2" aria-label={`${activeCategoryLabel} options`}>
                    <div className="res-cascade__head">
                      <button
                        type="button"
                        onClick={() => setActiveCategory(null)}
                        aria-label="Back to filter categories"
                        className="res-cascade__back"
                      >
                        <ChevronLeft size={18} aria-hidden="true" />
                        {activeCategoryLabel}
                      </button>
                      <h3 className="res-cascade__title">{activeCategoryLabel}</h3>
                      <button type="button" onClick={closeFilter} aria-label="Close filters" className="res-cascade__close">
                        <X size={18} aria-hidden="true" />
                      </button>
                    </div>
                    <ul className="res-cascade__opts">
                      {optionsForCategory(activeCategory).map((opt) => {
                        const selected = draftValue(activeCategory) === opt.value;
                        return (
                          <li key={opt.value}>
                            <button
                              type="button"
                              className="res-cascade__optbtn"
                              aria-pressed={selected}
                              onClick={() => setDraftValue(activeCategory, opt.value)}
                            >
                              <span className="res-cascade__optlabel">{opt.label}</span>
                              {selected && (
                                <span className="res-cascade__check" aria-hidden="true">
                                  <Check size={16} aria-hidden="true" />
                                </span>
                              )}
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                    <div className="res-cascade__actions2">
                      <Button variant="outline" onClick={resetFilters}>Reset</Button>
                      <Button onClick={applyFilters}>Apply</Button>
                    </div>
                  </div>
                )}
              </div>
            </>
          )}
        </div>
        <div className="res-toolbar__search">
          <Input
            placeholder="Search reservations..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            aria-label="Search reservations"
          />
        </div>
      </div>
      <p className="res-toolbar__meta">
        {activeRooms} kamar aktif
        {activeFilterCount > 0 ? ` · ${activeFilterCount} filter${activeFilterCount === 1 ? '' : 's'} active` : ''}
      </p>

      <CalendarView
        month={month}
        onMonthChange={handleMonthChange}
        filterRoomId={appliedRoom !== 'all' ? appliedRoom : undefined}
        filterStatus={appliedStatus !== 'all' ? appliedStatus : undefined}
        filterSearch={search}
        onDateClick={(day) => setSelectedDate(day)}
      />

      <section className="res-board" aria-labelledby="res-cal-chart-title" style={{ marginTop: '20px' }}>
        <h2 id="res-cal-chart-title" className="res-board__title">Distribusi Reservasi</h2>
        <p className="res-board__sub">Jumlah reservasi per status · Total {statusCounts.total}</p>
        <div role="img" aria-label={chartSummary}>
          {STATUS_BARS.map((s) => (
            <div className="res-bar" key={s.key} title={`${s.label}: ${statusCounts[s.key] ?? 0}`}>
              <span className="res-bar__label">{s.label}</span>
              <span className="res-bar__track">
                <span
                  className="res-bar__fill"
                  style={{
                    display: 'block',
                    width: mounted ? `${Math.max((statusCounts[s.key] ?? 0) > 0 ? 2 : 0, ((statusCounts[s.key] ?? 0) / maxCount) * 100)}%` : '0%',
                    backgroundColor: s.color,
                  }}
                />
              </span>
              <span className="res-bar__value">{statusCounts[s.key] ?? 0}</span>
            </div>
          ))}
        </div>
      </section>

      <DayReservationsPopup
        date={selectedDate}
        filterRoomId={appliedRoom !== 'all' ? appliedRoom : undefined}
        filterStatus={appliedStatus !== 'all' ? appliedStatus : undefined}
        onClose={() => setSelectedDate(null)}
        onViewAll={handleViewAll}
      />
    </div>
  );
}

import { useState, useMemo, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Filter, X, Check, ChevronRight, ChevronLeft } from 'lucide-react';
import { reservationService } from '@/services/reservationService';
import { roomService } from '@/services/roomService';
import { roomTypeService } from '@/services/roomTypeService';
import { invoiceService } from '@/services/invoiceService';
import { ReservationCard } from '@/components/shared/ReservationCard';
import { Button } from '@/components/shared/Button';
import { Card } from '@/components/shared/Card';
import { Input } from '@/components/shared/Input';
import { Pagination } from '@/components/shared/Pagination';
import { ReservationWizardModal } from '@/components/shared/ReservationWizardModal';
import { reservationSources, reservationSourceLabels, reservationStatusLabels } from '@/constants/reservationStatuses';
import { paymentStatuses } from '@/constants/invoiceStatuses';
import '../../styles/reservation-boards.css';
import '../../styles/reservation-list.css';

const STATUS_BARS = [
  { key: 'total', label: 'Total Reservasi', color: '#232D36' },
  { key: 'reserved', label: 'Reserved', color: '#97764D' },
  { key: 'checked-in', label: 'Checked In', color: '#2F5D37' },
  { key: 'checked-out', label: 'Checked Out', color: '#6B7881' },
  { key: 'cancelled', label: 'Cancelled', color: '#962222' },
];

interface ReservationFilters {
  status: string;
  source: string;
  date: string;
  roomType: string;
  payment: string;
}

const DEFAULT_FILTERS: ReservationFilters = {
  status: 'all',
  source: 'all',
  date: '',
  roomType: 'all',
  payment: 'all',
};

type FilterCategoryKey = 'status' | 'source' | 'roomType' | 'date' | 'payment';

type QuickRangeKey = 'all' | 'today' | 'weekly' | 'monthly' | 'month';

const QUICK_RANGES: Array<{ key: QuickRangeKey; label: string }> = [
  { key: 'all', label: 'All' },
  { key: 'today', label: 'Today' },
  { key: 'weekly', label: 'Weekly' },
  { key: 'monthly', label: 'Monthly' },
];

function stripTime(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

/**
 * Quick-range bounds for weekly/monthly, anchored on the real today.
 * Week follows the id-ID locale convention (Monday start), consistent with
 * the application's existing date handling. 'all' shows every reservation
 * (no date restriction); overlap uses the same
 * stay-overlaps-day semantics as the main date filter.
 */
function quickRangeBounds(range: QuickRangeKey): { start: Date; end: Date } | null {
  if (range === 'all') return null;
  const today = stripTime(new Date());
  if (range === 'today') return { start: today, end: today };
  if (range === 'weekly') {
    const monday = new Date(today);
    monday.setDate(today.getDate() - ((today.getDay() + 6) % 7));
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    return { start: monday, end: sunday };
  }
  return {
    start: new Date(today.getFullYear(), today.getMonth(), 1),
    end: new Date(today.getFullYear(), today.getMonth() + 1, 0),
  };
}

function staysInRange(checkInDate: string, checkOutDate: string, range: QuickRangeKey, month = ''): boolean {
  if (range === 'all') return true;
  const bounds = range === 'month' ? monthBounds(month) : quickRangeBounds(range);
  if (!bounds) return true;
  const ci = stripTime(new Date(checkInDate));
  const co = stripTime(new Date(checkOutDate));
  return ci <= bounds.end && co >= bounds.start;
}

function monthBounds(ym: string): { start: Date; end: Date } | null {
  const m = /^(\d{4})-(\d{2})$/.exec(ym);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  if (mo < 1 || mo > 12) return null;
  return { start: new Date(y, mo - 1, 1), end: new Date(y, mo, 0) };
}

function monthLabel(ym: string): string {
  const d = new Date(`${ym}-01T00:00:00`);
  if (Number.isNaN(d.getTime())) return ym;
  return d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
}

const FILTER_CATEGORIES: Array<{ key: FilterCategoryKey; label: string }> = [
  { key: 'status', label: 'Status' },
  { key: 'source', label: 'Source' },
  { key: 'roomType', label: 'Room Type' },
  { key: 'date', label: 'Date' },
  { key: 'payment', label: 'Payment Status' },
];

function countActiveFilters(filters: ReservationFilters): number {
  let count = 0;
  if (filters.status !== 'all') count += 1;
  if (filters.source !== 'all') count += 1;
  if (filters.date) count += 1;
  if (filters.roomType !== 'all') count += 1;
  if (filters.payment !== 'all') count += 1;
  return count;
}

function matchesDate(checkInDate: string, checkOutDate: string, dateFilter: string): boolean {
  if (!dateFilter) return true;
  const day = new Date(`${dateFilter}T00:00:00`);
  if (Number.isNaN(day.getTime())) return true;
  const ci = new Date(checkInDate);
  const co = new Date(checkOutDate);
  const d = new Date(day.getFullYear(), day.getMonth(), day.getDate());
  const cIn = new Date(ci.getFullYear(), ci.getMonth(), ci.getDate());
  const cOut = new Date(co.getFullYear(), co.getMonth(), co.getDate());
  return d >= cIn && d <= cOut;
}

export default function ReservationListPage() {
  const service = reservationService;
  const [searchParams, setSearchParams] = useSearchParams();
  const [applied, setApplied] = useState<ReservationFilters>(() => ({
    ...DEFAULT_FILTERS,
    date: searchParams.get('date') || '',
  }));
  const [draft, setDraft] = useState<ReservationFilters>(applied);
  const [filterOpen, setFilterOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState<FilterCategoryKey | null>(null);
  const [search, setSearch] = useState('');
  const [quickRange, setQuickRange] = useState<QuickRangeKey>('all');
  const [quickMonth, setQuickMonth] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(8);
  const daftarRef = useRef<HTMLHeadingElement>(null);
  const [showForm, setShowForm] = useState(false);
  const [mounted, setMounted] = useState(false);
  const filterWrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const paramDate = searchParams.get('date') || '';
    setApplied((prev) => (prev.date === paramDate ? prev : { ...prev, date: paramDate }));
    setDraft((prev) => (prev.date === paramDate ? prev : { ...prev, date: paramDate }));
  }, [searchParams]);

  useEffect(() => {
    const t = window.setTimeout(() => setMounted(true), 60);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!filterOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (filterWrapRef.current && !filterWrapRef.current.contains(e.target as Node)) {
        setFilterOpen(false);
        setActiveCategory(null);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setFilterOpen(false);
        setActiveCategory(null);
      }
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [filterOpen]);

  const openFilter = () => {
    setDraft(applied);
    setActiveCategory(null);
    setFilterOpen(true);
  };

  const closeFilter = () => {
    setFilterOpen(false);
    setActiveCategory(null);
  };

  const applyFilters = () => {
    setApplied(draft);
    setSearchParams(draft.date ? { date: draft.date } : {}, { replace: true });
    setCurrentPage(1);
    closeFilter();
  };

  const resetFilters = () => {
    setDraft({ ...DEFAULT_FILTERS });
    setApplied({ ...DEFAULT_FILTERS });
    setSearchParams({}, { replace: true });
    setCurrentPage(1);
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
    const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    daftarRef.current?.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
  };

  const [reservations, setReservations] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [allRooms, setAllRooms] = useState<Array<{ id: string; roomNumber: string; roomTypeId: string }>>([]);
  const [allTypes, setAllTypes] = useState<Array<{ id: string; name: string }>>([]);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setLoadError('');
    service.getAll().then((rows) => {
      if (!cancelled) {
        setReservations(rows);
        setIsLoading(false);
      }
    }).catch(() => {
      if (!cancelled) {
        setLoadError('Failed to load reservations');
        setIsLoading(false);
      }
    });
    roomService.getAll().then((rows) => {
      if (!cancelled) setAllRooms(rows);
    }).catch(() => {
      if (!cancelled) setAllRooms([]);
    });
    roomTypeService.getAll().then((rows) => {
      if (!cancelled) setAllTypes(rows);
    }).catch(() => {
      if (!cancelled) setAllTypes([]);
    });
    return () => {
      cancelled = true;
    };
  }, [showForm, service]);
  const invoiceByReservationId = useMemo(() => {
    return new Map(invoiceService.getAll().map((inv) => [inv.reservationId, inv]));
  }, []);

  const filteredReservations = useMemo(() => {
    const roomTypeByRoomId = new Map(allRooms.map((r) => [r.id, r.roomTypeId]));
    return reservations.filter((r) => {
      if (applied.source !== 'all' && r.source !== applied.source) return false;
      if (applied.status !== 'all' && r.status !== applied.status) return false;
      if (!matchesDate(r.checkInDate, r.checkOutDate, applied.date)) return false;
      if (!staysInRange(r.checkInDate, r.checkOutDate, quickRange, quickMonth)) return false;
      const matchesSearch = r.guestName.toLowerCase().includes(search.toLowerCase()) ||
        r.reservationCode.toLowerCase().includes(search.toLowerCase());
      if (!matchesSearch) return false;
      if (applied.roomType !== 'all') {
        const rooms = (r as any).rooms ?? [];
        const hasType = rooms.some((room: any) => roomTypeByRoomId.get(room.roomId) === applied.roomType);
        if (!hasType) return false;
      }
      if (applied.payment !== 'all') {
        const invoice = invoiceByReservationId.get(r.id);
        if (!invoice || invoice.paymentStatus !== applied.payment) return false;
      }
      return true;
    });
  }, [reservations, applied, search, quickRange, quickMonth, service, invoiceByReservationId, allRooms]);

  const monthOptions = useMemo(() => {
    const months = new Set<string>();
    reservations.forEach((r) => {
      months.add(r.checkInDate.substring(0, 7));
      months.add(r.checkOutDate.substring(0, 7));
    });
    return Array.from(months)
      .sort()
      .map((value) => ({ value, label: monthLabel(value) }));
  }, [reservations]);

  const totalPages = Math.max(1, Math.ceil(filteredReservations.length / pageSize));
  const safePage = Math.min(currentPage, totalPages);
  // Pager stays mounted whenever more than one page exists so the page-size
  // selector (and page buttons) remain clickable after changing the size,
  // even when the result fits on a single page.
  const usePagination = totalPages > 1;
  const visibleReservations = usePagination
    ? filteredReservations.slice((safePage - 1) * pageSize, safePage * pageSize)
    : filteredReservations;

  const statusCounts = useMemo(() => {
    const counts: Record<string, number> = { total: reservations.length };
    for (const s of STATUS_BARS.slice(1)) {
      counts[s.key] = reservations.filter((r) => r.status === s.key).length;
    }
    return counts;
  }, [reservations]);

  const activeFilterCount = countActiveFilters(applied);

  const isCategoryActive = (key: FilterCategoryKey, filters: ReservationFilters): boolean => {
    if (key === 'date') return filters.date !== '';
    return filters[key] !== 'all';
  };

  const categorySummary = (key: FilterCategoryKey, filters: ReservationFilters): string => {
    if (key === 'status') return filters.status === 'all' ? '' : (reservationStatusLabels[filters.status] || filters.status);
    if (key === 'source') return filters.source === 'all' ? '' : (reservationSourceLabels[filters.source] || filters.source);
    if (key === 'roomType') {
      if (filters.roomType === 'all') return '';
      return allTypes.find((t) => t.id === filters.roomType)?.name || '';
    }
    if (key === 'date') return filters.date;
    return filters.payment === 'all' ? '' : filters.payment;
  };

  const optionsForCategory = (key: FilterCategoryKey): Array<{ value: string; label: string }> => {
    if (key === 'status') {
      return [
        { value: 'all', label: 'All Status' },
        { value: 'reserved', label: 'Reserved' },
        { value: 'checked-in', label: 'Checked In' },
        { value: 'checked-out', label: 'Checked Out' },
        { value: 'cancelled', label: 'Cancelled' },
      ];
    }
    if (key === 'source') {
      return [
        { value: 'all', label: 'All Sources' },
        ...reservationSources.map((s) => ({ value: s, label: reservationSourceLabels[s] || s })),
      ];
    }
    if (key === 'roomType') {
      return [
        { value: 'all', label: 'All Room Types' },
        ...allTypes.map((rt) => ({ value: rt.id, label: rt.name })),
      ];
    }
    return [
      { value: 'all', label: 'All Payments' },
      ...paymentStatuses.map((p) => ({ value: p, label: p })),
    ];
  };

  const activeCategoryLabel = activeCategory
    ? FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label || ''
    : '';
  const maxCount = Math.max(1, ...Object.values(statusCounts));
  const chartSummary = `Distribusi reservasi. ${STATUS_BARS.map((s) => `${s.label} ${statusCounts[s.key] ?? 0}`).join(', ')}.`;

  return (
    <div style={{ padding: 'var(--space-xl, 20px)', maxWidth: '1400px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', marginBottom: '20px' }}>
        <div>
          <h1 style={{ fontSize: '24px', fontWeight: 700, color: '#232D36', fontFamily: 'var(--font-family-sans)', margin: 0 }}>Reservations</h1>
          <p style={{ color: '#6B7881', margin: '4px 0 0 0', fontSize: '14px' }}>Manage all reservations</p>
        </div>
        <Button onClick={() => setShowForm(true)}>+ New Reservation</Button>
      </div>

      <div className="res-toolbar" role="search">
        <div className="res-toolbar__filterwrap" ref={filterWrapRef}>
          <Button
            onClick={() => (filterOpen ? setFilterOpen(false) : openFilter())}
            aria-expanded={filterOpen}
            aria-controls="reservation-filter-panel"
            aria-label={activeFilterCount > 0 ? `Filter, ${activeFilterCount} active` : 'Filter'}
          >
            <Filter size={16} aria-hidden="true" />
            <span style={{ marginLeft: '8px' }}>Filter</span>
            {activeFilterCount > 0 && (
              <span className="res-filterbtn-count" aria-hidden="true">{activeFilterCount}</span>
            )}
          </Button>

          {filterOpen && (
            <>
              <button
                type="button"
                className="res-filter-scrim"
                aria-label="Close filters"
                onClick={closeFilter}
                tabIndex={-1}
              />
              <div className={`res-cascade${activeCategory ? ' res-cascade--split res-cascade--detail' : ''}`}>
                <div
                  className="res-cascade__panel1"
                  role="dialog"
                  aria-label="Reservation filters"
                >
                  <div className="res-cascade__head">
                    <h2 className="res-cascade__title">Filter</h2>
                    <button
                      type="button"
                      onClick={closeFilter}
                      aria-label="Close filters"
                      className="res-cascade__close"
                    >
                      <X size={18} aria-hidden="true" />
                    </button>
                  </div>
                  <ul className="res-cascade__cats">
                    {FILTER_CATEGORIES.map((cat) => {
                      const active = isCategoryActive(cat.key, draft);
                      const summary = categorySummary(cat.key, draft);
                      const selected = activeCategory === cat.key;
                      return (
                        <li key={cat.key}>
                          <button
                            type="button"
                            className={`res-cascade__catbtn${active ? ' res-cascade__catbtn--active' : ''}`}
                            aria-expanded={selected}
                            onClick={() => setActiveCategory(selected ? null : cat.key)}
                          >
                            <span className="res-cascade__catlabel">{cat.label}</span>
                            {summary && <span className="res-cascade__catsub">{summary}</span>}
                            {active && (
                              <span className="res-cascade__check" aria-hidden="true">
                                <Check size={16} aria-hidden="true" />
                              </span>
                            )}
                            <span className="res-cascade__chev" aria-hidden="true">
                              <ChevronRight size={16} aria-hidden="true" />
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                  <div className="res-cascade__actions">
                    <Button variant="outline" onClick={resetFilters}>Reset</Button>
                    <Button onClick={applyFilters}>Apply</Button>
                  </div>
                </div>

                {activeCategory && (
                  <div className="res-cascade__panel2" aria-label={`${activeCategoryLabel} options`}>
                    <div className="res-cascade__head">
                      <button
                        type="button"
                        onClick={() => setActiveCategory(null)}
                        aria-label="Back to filter categories"
                        className="res-cascade__back"
                      >
                        <ChevronLeft size={18} aria-hidden="true" />
                        {activeCategoryLabel}
                      </button>
                      <h3 className="res-cascade__title">{activeCategoryLabel}</h3>
                      <button
                        type="button"
                        onClick={closeFilter}
                        aria-label="Close filters"
                        className="res-cascade__close"
                      >
                        <X size={18} aria-hidden="true" />
                      </button>
                    </div>
                    {activeCategory === 'date' ? (
                      <div className="res-cascade__datewrap">
                        <Input
                          label="Select date"
                          type="date"
                          value={draft.date}
                          onChange={(e) => setDraft({ ...draft, date: e.target.value })}
                        />
                        {draft.date && (
                          <button
                            type="button"
                            className="res-cascade__clearbtn"
                            onClick={() => setDraft({ ...draft, date: '' })}
                          >
                            Clear date
                          </button>
                        )}
                      </div>
                    ) : (
                      <ul className="res-cascade__opts">
                        {optionsForCategory(activeCategory).map((opt) => {
                          const selected = draft[activeCategory] === opt.value;
                          return (
                            <li key={opt.value}>
                              <button
                                type="button"
                                className="res-cascade__optbtn"
                                aria-pressed={selected}
                                onClick={() => setDraft({ ...draft, [activeCategory]: opt.value })}
                              >
                                <span className="res-cascade__optlabel">{opt.label}</span>
                                {selected && (
                                  <span className="res-cascade__check" aria-hidden="true">
                                    <Check size={16} aria-hidden="true" />
                                  </span>
                                )}
                              </button>
                            </li>
                          );
                        })}
                      </ul>
                    )}
                    <div className="res-cascade__actions2">
                      <Button variant="outline" onClick={resetFilters}>Reset</Button>
                      <Button onClick={applyFilters}>Apply</Button>
                    </div>
                  </div>
                )}
              </div>
            </>
          )}
        </div>
        <div className="res-toolbar__search">
          <Input
            placeholder="Search reservations..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setCurrentPage(1); }}
            aria-label="Search reservations"
          />
        </div>
      </div>

      <section className="res-board" aria-labelledby="res-chart-title" style={{ marginBottom: '20px' }}>
        <h2 id="res-chart-title" className="res-board__title">Distribusi Reservasi</h2>
        <p className="res-board__sub">Jumlah reservasi per status · Total {statusCounts.total}</p>
        <div role="img" aria-label={chartSummary}>
          {STATUS_BARS.map((s) => (
            <div className="res-bar" key={s.key} title={`${s.label}: ${statusCounts[s.key] ?? 0}`}>
              <span className="res-bar__label">{s.label}</span>
              <span className="res-bar__track">
                <span
                  className="res-bar__fill"
                  style={{
                    display: 'block',
                    width: mounted ? `${Math.max((statusCounts[s.key] ?? 0) > 0 ? 2 : 0, ((statusCounts[s.key] ?? 0) / maxCount) * 100)}%` : '0%',
                    backgroundColor: s.color,
                  }}
                />
              </span>
              <span className="res-bar__value">{statusCounts[s.key] ?? 0}</span>
            </div>
          ))}
        </div>
      </section>

      <div className="res-daftarhead">
        <h2 ref={daftarRef} className="res-board__title" style={{ margin: 0, scrollMarginTop: '16px' }}>Daftar Reservasi</h2>
        <div className="res-qpills" role="group" aria-label="Quick date filter">
          {QUICK_RANGES.map((opt) => (
            <button
              key={opt.key}
              type="button"
              onClick={() => { setQuickRange(opt.key); setQuickMonth(''); setCurrentPage(1); }}
              aria-pressed={quickRange === opt.key}
              className={quickRange === opt.key ? 'res-qpill res-qpill--active' : 'res-qpill'}
            >
              {opt.label}
            </button>
          ))}
          <select
            className={`res-qmonth${quickRange === 'month' ? ' res-qmonth--active' : ''}`}
            aria-label="Filter by specific month"
            value={quickRange === 'month' ? quickMonth : ''}
            onChange={(e) => {
              const v = e.target.value;
              setQuickMonth(v);
              setQuickRange(v ? 'month' : 'all');
              setCurrentPage(1);
            }}
          >
            <option value="">Select month</option>
            {monthOptions.map((o) => (
              <option key={o.value} value={o.value}>{o.label}</option>
            ))}
          </select>
        </div>
      </div>
      <p className="res-toolbar__meta">
        {usePagination
          ? `Showing ${(safePage - 1) * pageSize + 1}–${Math.min(safePage * pageSize, filteredReservations.length)} of ${filteredReservations.length} result(s)`
          : `${filteredReservations.length} result(s)`}
        {applied.date ? ` · filtered to ${applied.date}` : ''}
        {quickRange === 'month' && quickMonth ? ` · ${monthLabel(quickMonth)}` : ''}
        {activeFilterCount > 0 ? ` · ${activeFilterCount} filter${activeFilterCount === 1 ? '' : 's'} active` : ''}
      </p>

      {loadError && <div role="alert" style={{ color: '#C85C5C', fontSize: '14px', marginBottom: '12px' }}>{loadError}</div>}

      <div className="res-list">
        {visibleReservations.map((reservation) => {
          const rooms = (reservation as any).rooms ?? [];
          return (
            <ReservationCard
              key={reservation.id}
              reservation={{
                ...reservation,
                rooms: rooms.map((r: any) => ({ roomNumber: r.roomNumber, roomTypeName: r.roomTypeName })),
                paymentStatus: invoiceByReservationId.get(reservation.id)?.paymentStatus,
              }}
            />
          );
        })}
      </div>

      {filteredReservations.length === 0 && (
        <Card style={{ textAlign: 'center', padding: '40px' }}>
          <p style={{ color: '#6B7881', fontSize: '14px' }}>{isLoading ? 'Loading reservations...' : 'No reservations found'}</p>
        </Card>
      )}

      {usePagination && (
        <Pagination
          currentPage={safePage}
          totalPages={totalPages}
          totalItems={filteredReservations.length}
          pageSize={pageSize}
          onPageChange={handlePageChange}
          onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
        />
      )}

      {showForm && (
        <ReservationWizardModal open={showForm} onClose={() => setShowForm(false)} onSaved={() => setShowForm(false)} />
      )}
    </div>
  );
}

import { useState, useMemo, useEffect, useRef } from 'react';
import { Filter, X, Check, ChevronRight, ChevronLeft } from 'lucide-react';
import { Button } from '@/components/shared/Button';
import { Badge } from '@/components/shared/Badge';
import { Input } from '@/components/shared/Input';
import { Table } from '@/components/shared/Table';
import { Modal } from '@/components/shared/Modal';
import { Pagination } from '@/components/shared/Pagination';
import { RoleForm } from '@/components/shared/RoleForm';
import roleService from '@/services/roleService';
import '../../styles/admin-responsive.css';
import '../../styles/reservation-list.css';

type RoleModal = { mode: 'create' } | { mode: 'edit'; id: string } | null;

const FILTER_CATEGORIES = [
  {
    key: 'status',
    label: 'Status',
    options: [
      { value: 'all', label: 'All Status' },
      { value: 'active', label: 'Active' },
      { value: 'inactive', label: 'Inactive' },
    ],
  },
];

export default function RoleListPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [modal, setModal] = useState<RoleModal>(null);
  const [filterOpen, setFilterOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [draft, setDraft] = useState<Record<string, string>>({ status: 'all' });
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const filterWrapRef = useRef<HTMLDivElement>(null);
  const [roles, setRoles] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [reloadToken, setReloadToken] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setLoadError('');
    roleService.getAll().then((r) => {
      if (!cancelled) {
        setRoles(r);
        setIsLoading(false);
      }
    }).catch(() => {
      if (!cancelled) {
        setLoadError('Failed to load roles');
        setIsLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [reloadToken]);

  const handleModalSuccess = () => {
    closeModal();
    setReloadToken((t) => t + 1);
  };

  const filtered = useMemo(() => {
    return roles.filter((r: any) => {
      const matchesSearch = r.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || r.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [roles, searchTerm, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const safePage = Math.min(currentPage, totalPages);
  const visibleRoles = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);

  const activeFilterCount = statusFilter !== 'all' ? 1 : 0;

  const applyFilters = () => {
    setStatusFilter(draft.status);
    setFilterOpen(false);
    setCurrentPage(1);
  };

  const resetFilters = () => {
    setDraft({ status: 'all' });
    setStatusFilter('all');
    setActiveCategory(null);
    setCurrentPage(1);
  };

  const closeFilter = () => {
    setFilterOpen(false);
    setActiveCategory(null);
  };

  useEffect(() => {
    if (!filterOpen) return;
    const onDocClick = (e: MouseEvent) => {
      if (filterWrapRef.current && !filterWrapRef.current.contains(e.target as Node)) {
        closeFilter();
      }
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [filterOpen]);

  const closeModal = () => setModal(null);

  const columns = [
    { key: 'name', header: 'Role Name', render: (item: any) => item.name },
    { key: 'description', header: 'Description', render: (item: any) => item.description },
    { key: 'permissionCount', header: 'Permissions', render: (item: any) => item.permissions?.length || 0 },
    { key: 'status', header: 'Status', render: (item: any) => (
      <Badge variant={item.status === 'active' ? 'success' : 'default'}>{item.status}</Badge>
    )},
    { key: 'actions', header: 'Actions', render: (item: any) => (
      <div style={{ display: 'flex', gap: '4px', justifyContent: 'center' }}>
        <Button variant="ghost" size="sm" onClick={() => setModal({ mode: 'edit', id: item.id })} style={{ backgroundColor: 'transparent', color: '#232D36', borderColor: '#97764D' }} hoverStyle={{ backgroundColor: '#232D36', color: '#FFFFFF', borderColor: '#232D36' }}>Edit</Button>
      </div>
    )},
  ];

  return (
    <div className="adm-page">
      <div className="adm-head">
        <div>
          <h1 className="adm-h1">Jabatan</h1>
          <p className="adm-sub">Manage roles and their permissions</p>
        </div>
        <Button variant="primary" className="adm-cta" onClick={() => setModal({ mode: 'create' })}>Create Role</Button>
      </div>
      <div className="res-toolbar" role="search" style={{ marginBottom: '20px' }}>
        <div className="res-toolbar__filterwrap" ref={filterWrapRef}>
          <Button
            onClick={() => (filterOpen ? closeFilter() : setFilterOpen(true))}
            aria-expanded={filterOpen}
            aria-controls="role-filter-panel"
            aria-label={activeFilterCount > 0 ? `Filter, ${activeFilterCount} active` : 'Filter'}
          >
            <Filter size={16} aria-hidden="true" />
            <span style={{ marginLeft: '8px' }}>Filter</span>
            {activeFilterCount > 0 && (
              <span className="res-filterbtn-count" aria-hidden="true">{activeFilterCount}</span>
            )}
          </Button>

          {filterOpen && (
            <>
              <button
                type="button"
                className="res-filter-scrim"
                aria-label="Close filters"
                onClick={closeFilter}
                tabIndex={-1}
              />
              <div className={`res-cascade${activeCategory ? ' res-cascade--split res-cascade--detail' : ''}`}>
                <div className="res-cascade__panel1" role="dialog" aria-label="Role filters">
                  <div className="res-cascade__head">
                    <h2 className="res-cascade__title">Filter</h2>
                    <button
                      type="button"
                      onClick={closeFilter}
                      aria-label="Close filters"
                      className="res-cascade__close"
                    >
                      <X size={18} aria-hidden="true" />
                    </button>
                  </div>
                  <ul className="res-cascade__cats">
                    {FILTER_CATEGORIES.map((cat) => {
                      const active = draft[cat.key] !== 'all';
                      const selected = activeCategory === cat.key;
                      return (
                        <li key={cat.key}>
                          <button
                            type="button"
                            className={`res-cascade__catbtn${active ? ' res-cascade__catbtn--active' : ''}`}
                            aria-expanded={selected}
                            onClick={() => setActiveCategory(selected ? null : cat.key)}
                          >
                            <span className="res-cascade__catlabel">{cat.label}</span>
                            {active && (
                              <span className="res-cascade__catsub">
                                {cat.options.find((o) => o.value === draft[cat.key])?.label}
                              </span>
                            )}
                            <span className="res-cascade__chev" aria-hidden="true">
                              <ChevronRight size={16} aria-hidden="true" />
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                  <div className="res-cascade__actions">
                    <Button variant="outline" onClick={resetFilters}>Reset</Button>
                    <Button onClick={applyFilters}>Apply</Button>
                  </div>
                </div>

                {activeCategory && (
                  <div className="res-cascade__panel2" aria-label={`${FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label} options`}>
                    <div className="res-cascade__head">
                      <button
                        type="button"
                        onClick={() => setActiveCategory(null)}
                        aria-label="Back to filter categories"
                        className="res-cascade__back"
                      >
                        <ChevronLeft size={18} aria-hidden="true" />
                        {FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label}
                      </button>
                      <h3 className="res-cascade__title">{FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label}</h3>
                      <button
                        type="button"
                        onClick={closeFilter}
                        aria-label="Close filters"
                        className="res-cascade__close"
                      >
                        <X size={18} aria-hidden="true" />
                      </button>
                    </div>
                    <ul className="res-cascade__opts">
                      {FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.options.map((opt) => {
                        const selected = draft[activeCategory] === opt.value;
                        return (
                          <li key={opt.value}>
                            <button
                              type="button"
                              className="res-cascade__optbtn"
                              aria-pressed={selected}
                              onClick={() => setDraft({ ...draft, [activeCategory]: opt.value })}
                            >
                              <span className="res-cascade__optlabel">{opt.label}</span>
                              {selected && (
                                <span className="res-cascade__check" aria-hidden="true">
                                  <Check size={16} aria-hidden="true" />
                                </span>
                              )}
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                    <div className="res-cascade__actions2">
                      <Button variant="outline" onClick={resetFilters}>Reset</Button>
                      <Button onClick={applyFilters}>Apply</Button>
                    </div>
                  </div>
                )}
              </div>
            </>
          )}
        </div>
        <div className="res-toolbar__search" style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <Input
            placeholder="Search roles..."
            value={searchTerm}
            onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}
            aria-label="Search roles"
          />
          <span className="adm-count" style={{ whiteSpace: 'nowrap' }}>
            {filtered.length} result(s)
          </span>
        </div>
      </div>
      {loadError && <div role="alert" style={{ color: '#C85C5C', fontSize: '14px', marginBottom: '12px' }}>{loadError}</div>}
      <Table columns={columns} data={visibleRoles} emptyMessage={isLoading ? 'Loading roles...' : 'No roles found'} />
      {filtered.length > 0 && (
        <Pagination
          currentPage={safePage}
          totalPages={totalPages}
          totalItems={filtered.length}
          pageSize={pageSize}
          pageSizeOptions={[10, 20, 50]}
          onPageChange={setCurrentPage}
          onPageSizeChange={(size) => { setPageSize(size); setCurrentPage(1); }}
        />
      )}

      <Modal
        open={modal !== null}
        onClose={closeModal}
        title={modal?.mode === 'edit' ? 'Edit Role' : 'Create Role'}
        size="lg"
      >
        {modal !== null && (
          <RoleForm
            key={modal.mode === 'edit' ? modal.id : 'new'}
            id={modal.mode === 'edit' ? modal.id : undefined}
            onSuccess={handleModalSuccess}
            onCancel={closeModal}
          />
        )}
      </Modal>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Pencil } from 'lucide-react';
import { Button } from '@/components/shared/Button';
import { Modal } from '@/components/shared/Modal';
import { UserForm } from '@/components/shared/UserForm';
import userService from '@/services/userService';
import roleService from '@/services/roleService';
import { Card } from '@/components/shared/Card';
import { Badge } from '@/components/shared/Badge';
import { PAGE_PERMISSIONS } from '@/config/permissions';
import {
  computeEffectivePermissions,
  getUserPermissionOverride,
  type UserPermissionOverride,
} from '@/services/userPermissionService';
import '../../styles/admin-responsive.css';

export default function UserDetailPage() {
  const { id } = useParams<{ id: string }>();
  const [showEdit, setShowEdit] = useState(false);
  const [user, setUser] = useState<any | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [allRoles, setAllRoles] = useState<any[]>([]);
  const [override, setOverride] = useState<UserPermissionOverride>({ grants: [], denies: [], updatedAt: '' });

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    setIsLoading(true);
    userService.getById(id).then((u) => {
      if (!cancelled) {
        setUser(u ?? null);
        setIsLoading(false);
      }
    }).catch(() => {
      if (!cancelled) {
        setUser(null);
        setIsLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [id, showEdit]);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    Promise.all([
      roleService.getAll().catch(() => [] as any[]),
      getUserPermissionOverride(id),
    ]).then(([roles, o]) => {
      if (cancelled) return;
      setAllRoles(roles);
      setOverride(o);
    });
    return () => {
      cancelled = true;
    };
  }, [id, showEdit]);

  const rolePerms = useMemo(() => {
    const set = new Set<string>();
    const userRoleIds: string[] = Array.isArray(user?.roles) ? user.roles : [];
    for (const r of allRoles) {
      if (userRoleIds.includes(r.id) && Array.isArray(r.permissions)) {
        for (const p of r.permissions) {
          if (typeof p === 'string') set.add(p);
        }
      }
    }
    return set;
  }, [allRoles, user]);

  const effective = useMemo(
    () => new Set(computeEffectivePermissions([...rolePerms], override)),
    [rolePerms, override],
  );

  if (isLoading) {
    return (
      <div style={{ padding: 'var(--space-xl, 20px)', textAlign: 'center' }}>
        <p style={{ color: '#6B7881' }}>Loading user...</p>
      </div>
    );
  }

  if (!user) {
    return (
      <div style={{ padding: 'var(--space-xl, 20px)', textAlign: 'center' }}>
        <h2 style={{ color: '#232D36', fontFamily: 'var(--font-family-sans)' }}>User not found</h2>
        <Link to="/dashboard/users" style={{ color: '#97764D', fontWeight: 600 }}>Back to Users</Link>
      </div>
    );
  }

  return (
    <div className="adm-page adm-page--narrow">
      <div className="adm-head">
        <h1 className="adm-h1">User Details</h1>
        <Button variant="outline" className="adm-cta" aria-label="Edit user" onClick={() => setShowEdit(true)}><Pencil size={14} aria-hidden="true" /></Button>
      </div>
      <Card title="User Information">
        <div style={{ display: 'grid', gap: 'var(--space-md, 12px)' }}>
          {[
            { label: 'Name', value: user.name },
            { label: 'Email', value: user.email },
            { label: 'Status', value: user.status },
            { label: 'Roles', value: user.roles?.map((r: string) => r.replace('role-', 'Role ')).join(', ') || '-' },
            { label: 'Created', value: new Date(user.createdAt).toLocaleDateString() },
            { label: 'Last Login', value: user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleDateString() : 'N/A' },
          ].map((item) => (
            <div key={item.label} style={{ display: 'flex', justifyContent: 'space-between', padding: 'var(--space-sm, 8px) 0', borderBottom: '1px solid #C7BBAB' }}>
              <span style={{ fontWeight: 500, color: '#6B7881' }}>{item.label}</span>
              <span style={{ fontWeight: 600, color: '#232D36' }}>{item.value}</span>
            </div>
          ))}
        </div>
      </Card>
      <Card title="Permissions">
        <p style={{ fontSize: '12px', color: '#6B7881', margin: '0 0 12px' }}>
          Effective page access for this user: role permissions plus user-specific grants, minus revocations.
        </p>
        <div style={{ display: 'grid', gap: 'var(--space-sm, 8px)' }}>
          {PAGE_PERMISSIONS.map((perm) => {
            const granted = effective.has(perm.name);
            const userSpecific = override.grants.includes(perm.name) || override.denies.includes(perm.name);
            return (
              <div key={perm.name} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '12px', padding: 'var(--space-sm, 8px) 0', borderBottom: '1px solid #C7BBAB' }}>
                <span>
                  <span style={{ fontWeight: 600, color: '#232D36', fontSize: '13px' }}>{perm.label}</span>
                  <span style={{ color: '#6B7881', fontSize: '12px' }}> · {perm.name}</span>
                </span>
                {granted ? (
                  <Badge variant="success">{userSpecific ? 'Granted (user)' : 'Granted (role)'}</Badge>
                ) : (
                  <Badge variant="default">{userSpecific ? 'Revoked (user)' : 'No access'}</Badge>
                )}
              </div>
            );
          })}
        </div>
      </Card>
      <div style={{ marginTop: 'var(--space-lg, 16px)' }}>
        <Link to="/dashboard/users" className="adm-backlink"><ArrowLeft size={14} aria-hidden="true" /> Back to Users</Link>
      </div>

      <Modal open={showEdit} onClose={() => setShowEdit(false)} title="Edit User" size="md">
        <UserForm key={user.id} id={user.id} onSuccess={() => setShowEdit(false)} onCancel={() => setShowEdit(false)} />
      </Modal>
    </div>
  );
}

import { useState, useMemo, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { Filter, X, Check, ChevronRight, ChevronLeft } from 'lucide-react';
import { Table } from '@/components/shared/Table';
import { Button } from '@/components/shared/Button';
import { Badge } from '@/components/shared/Badge';
import { Input } from '@/components/shared/Input';
import { Modal } from '@/components/shared/Modal';
import { Pagination } from '@/components/shared/Pagination';
import { UserForm } from '@/components/shared/UserForm';
import { UserRoleForm } from '@/components/shared/UserRoleForm';
import { UserPermissionForm } from '@/components/shared/UserPermissionForm';
import userService from '@/services/userService';
import { usePermissions } from '@/hooks/usePermissions';
import '../../styles/admin-responsive.css';
import '../../styles/reservation-list.css';

type UserModal = { mode: 'create' } | { mode: 'assign'; id: string } | { mode: 'assignPerms'; id: string } | null;

const FILTER_CATEGORIES = [
  {
    key: 'status',
    label: 'Status',
    options: [
      { value: 'all', label: 'All Status' },
      { value: 'active', label: 'Active' },
      { value: 'inactive', label: 'Inactive' },
    ],
  },
];

export default function UserListPage() {
  const { hasPermission } = usePermissions();
  const canView = hasPermission('user.view');
  const canAssign = hasPermission('user.update');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [modal, setModal] = useState<UserModal>(null);
  const [filterOpen, setFilterOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [draft, setDraft] = useState<Record<string, string>>({ status: 'all' });
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const filterWrapRef = useRef<HTMLDivElement>(null);
  const [users, setUsers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [reloadToken, setReloadToken] = useState(0);
  const closeModal = () => setModal(null);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setLoadError('');
    userService.getAll().then((u) => {
      if (!cancelled) {
        setUsers(u);
        setIsLoading(false);
      }
    }).catch(() => {
      if (!cancelled) {
        setLoadError('Failed to load users');
        setIsLoading(false);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [reloadToken]);

  const handleModalSuccess = () => {
    closeModal();
    setReloadToken((t) => t + 1);
  };

  const filtered = useMemo(() => {
    return users.filter((u: any) => {
      const matchesSearch = u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.email.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || u.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [users, searchTerm, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const safePage = Math.min(currentPage, totalPages);
  const visibleUsers = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);

  const activeFilterCount = statusFilter !== 'all' ? 1 : 0;

  const applyFilters = () => {
    setStatusFilter(draft.status);
    setFilterOpen(false);
    setCurrentPage(1);
  };

  const resetFilters = () => {
    setDraft({ status: 'all' });
    setStatusFilter('all');
    setActiveCategory(null);
    setCurrentPage(1);
  };

  const closeFilter = () => {
    setFilterOpen(false);
    setActiveCategory(null);
  };

  useEffect(() => {
    if (!filterOpen) return;
    const onDocClick = (e: MouseEvent) => {
      if (filterWrapRef.current && !filterWrapRef.current.contains(e.target as Node)) {
        closeFilter();
      }
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [filterOpen]);

  const columns = [
    { key: 'name', header: 'Name', render: (item: any) => item.name },
    { key: 'email', header: 'Email', render: (item: any) => item.email },
    { key: 'roles', header: 'Role', render: (item: any) => item.roles?.map((r: string) => r.replace('role-', 'Role ')).join(', ') || '—' },
    { key: 'status', header: 'Status', render: (item: any) => (
      <Badge variant={item.status === 'active' ? 'success' : 'default'}>{item.status}</Badge>
    )},
    { key: 'actions', header: 'Actions', render: (item: any) => (
      <div style={{ display: 'flex', gap: '4px', justifyContent: 'center' }}>
        {canView && (
          <Link to={`/dashboard/users/${item.id}`} style={{ textDecoration: 'none', display: 'inline-flex' }}><button
            type="button"
            style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', height: '36px', padding: '0 12px', borderRadius: '8px', border: '1px solid #97764D', backgroundColor: 'transparent', color: '#232D36', fontSize: '12px', fontWeight: 600, fontFamily: 'var(--font-family-sans)', cursor: 'pointer', transition: 'background-color 150ms ease, color 150ms ease, border-color 150ms ease' }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#232D36'; e.currentTarget.style.color = '#FFFFFF'; e.currentTarget.style.borderColor = '#232D36'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'transparent'; e.currentTarget.style.color = '#232D36'; e.currentTarget.style.borderColor = '#97764D'; }}
          >View</button></Link>
        )}
        {canAssign && (
          <button
            type="button"
            onClick={() => setModal({ mode: 'assign', id: item.id })}
            style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', height: '36px', padding: '0 12px', borderRadius: '8px', border: '1px solid #232D36', backgroundColor: '#232D36', color: '#FFFFFF', fontSize: '12px', fontWeight: 600, fontFamily: 'var(--font-family-sans)', cursor: 'pointer', transition: 'background-color 150ms ease, color 150ms ease, border-color 150ms ease' }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#97764D'; e.currentTarget.style.color = '#FFFFFF'; e.currentTarget.style.borderColor = '#97764D'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#232D36'; e.currentTarget.style.color = '#FFFFFF'; e.currentTarget.style.borderColor = '#232D36'; }}
          >Assign Role</button>
        )}
        {canAssign && (
          <button
            type="button"
            onClick={() => setModal({ mode: 'assignPerms', id: item.id })}
            style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', height: '36px', padding: '0 12px', borderRadius: '8px', border: '1px solid #232D36', backgroundColor: '#232D36', color: '#FFFFFF', fontSize: '12px', fontWeight: 600, fontFamily: 'var(--font-family-sans)', cursor: 'pointer', transition: 'background-color 150ms ease, color 150ms ease, border-color 150ms ease' }}
            onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#97764D'; e.currentTarget.style.color = '#FFFFFF'; e.currentTarget.style.borderColor = '#97764D'; }}
            onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#232D36'; e.currentTarget.style.color = '#FFFFFF'; e.currentTarget.style.borderColor = '#232D36'; }}
          >Assign Permission</button>
        )}
      </div>
    )},
  ];

  return (
    <div className="adm-page">
      <div className="adm-head">
        <div>
          <h1 className="adm-h1">Pengguna</h1>
          <p className="adm-sub">Manage user accounts and role assignments</p>
        </div>
        <Button variant="primary" className="adm-cta" onClick={() => setModal({ mode: 'create' })}>Add User</Button>
      </div>
      <div className="res-toolbar" role="search" style={{ marginBottom: '20px' }}>
        <div className="res-toolbar__filterwrap" ref={filterWrapRef}>
          <Button
            onClick={() => (filterOpen ? closeFilter() : setFilterOpen(true))}
            aria-expanded={filterOpen}
            aria-controls="user-filter-panel"
            aria-label={activeFilterCount > 0 ? `Filter, ${activeFilterCount} active` : 'Filter'}
          >
            <Filter size={16} aria-hidden="true" />
            <span style={{ marginLeft: '8px' }}>Filter</span>
            {activeFilterCount > 0 && (
              <span className="res-filterbtn-count" aria-hidden="true">{activeFilterCount}</span>
            )}
          </Button>

          {filterOpen && (
            <>
              <button
                type="button"
                className="res-filter-scrim"
                aria-label="Close filters"
                onClick={closeFilter}
                tabIndex={-1}
              />
              <div className={`res-cascade${activeCategory ? ' res-cascade--split res-cascade--detail' : ''}`}>
                <div className="res-cascade__panel1" role="dialog" aria-label="User filters">
                  <div className="res-cascade__head">
                    <h2 className="res-cascade__title">Filter</h2>
                    <button
                      type="button"
                      onClick={closeFilter}
                      aria-label="Close filters"
                      className="res-cascade__close"
                    >
                      <X size={18} aria-hidden="true" />
                    </button>
                  </div>
                  <ul className="res-cascade__cats">
                    {FILTER_CATEGORIES.map((cat) => {
                      const active = draft[cat.key] !== 'all';
                      const selected = activeCategory === cat.key;
                      return (
                        <li key={cat.key}>
                          <button
                            type="button"
                            className={`res-cascade__catbtn${active ? ' res-cascade__catbtn--active' : ''}`}
                            aria-expanded={selected}
                            onClick={() => setActiveCategory(selected ? null : cat.key)}
                          >
                            <span className="res-cascade__catlabel">{cat.label}</span>
                            {active && (
                              <span className="res-cascade__catsub">
                                {cat.options.find((o) => o.value === draft[cat.key])?.label}
                              </span>
                            )}
                            <span className="res-cascade__chev" aria-hidden="true">
                              <ChevronRight size={16} aria-hidden="true" />
                            </span>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                  <div className="res-cascade__actions">
                    <Button variant="outline" onClick={resetFilters}>Reset</Button>
                    <Button onClick={applyFilters}>Apply</Button>
                  </div>
                </div>

                {activeCategory && (
                  <div className="res-cascade__panel2" aria-label={`${FILTER_CATEGORIES.find((c) => c.key === activeCategory)?.label} options`}>
                    <div className="res-cascade__head">
                      <button
                        type="button"
